const FACTOR_DESVIO_VIAL = 1.18;

const MAX_VUELTAS_POR_CAMION = 2;


// === Funciones ===

function buscarEnCatalogoSKU(codigo){
  if(!codigo) return null;
  const key = String(codigo).trim();
  return CATALOGO_SKU_MEDIDAS[key] || null;
}

function volumenUnitarioCatalogoM3(sku){
  const m = buscarEnCatalogoSKU(sku);
  if(!m) return null;
  const L=Number(m[0]), W=Number(m[1]), H=Number(m[2]);
  if(!(L>0&&W>0&&H>0)) return null;
  return (L*W*H)/1000000;
}

function normalizarVolumenLinea(p){
  if(!p) return p;
  const qty=Math.max(1, parseInt(p.cantidad,10)||1);
  const catalogoVol=volumenUnitarioCatalogoM3(p.sku);
  p._volumenOriginal = Number.isFinite(Number(p.volumen)) ? Number(p.volumen) : 0;
  p.cantidad=qty;
  if(catalogoVol!==null){
    p.volumen=Number((catalogoVol*qty).toFixed(6));
    p._volumenFuente='catalogo';
    p._volumenUnitarioCatalogo=Number(catalogoVol.toFixed(6));
  }else{
    p.volumen=Math.max(0, Number(p.volumen)||0);
    p._volumenFuente='entrada';
    p._volumenUnitarioCatalogo=null;
  }
  return p;
}

function comunaKeyResuelta(comuna){
  const key=norm(comuna);
  return COMUNA_ALIAS[key] || key;
}

function corredorOperativoDeStop(s){
  const comuna=comunaKeyResuelta(s&&s.comuna);
  for(const k of Object.keys(CORREDORES)){ if(CORREDORES[k].has(comuna)) return k; }
  return null;
}

function calcularEtiquetaPorContenido(stops){
  const conteo={};
  (stops||[]).forEach(function(s){
    const c=corredorOperativoDeStop(s);
    if(c){ const l=CORREDOR_LABEL[c]||c; conteo[l]=(conteo[l]||0)+1; }
  });
  const etiquetas=Object.keys(conteo).sort(function(a,b){return conteo[b]-conteo[a];});
  return etiquetas.length ? etiquetas.join(' + ') : null;
}

function zonaOperativaDeStop(s){
  const corredor=corredorOperativoDeStop(s);
  if(corredor) return CORREDOR_PADRE[corredor];
  const sub=s&&s._comunaInfo&&s._comunaInfo.sub;
  return MACRO_ZONAS[sub]||null;
}

function etiquetaOperativaDeStop(s){
  const corredor=corredorOperativoDeStop(s);
  return corredor ? CORREDOR_LABEL[corredor] : (zonaOperativaDeStop(s)||'Sin sector');
}

function norm(s){
  return (s||"").toString().normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase().trim();
}

function _distEdicion(a,b){ const m=a.length,n=b.length; const d=[]; for(let i=0;i<=m;i++){d[i]=[i];} for(let j=1;j<=n;j++) d[0][j]=j;
  for(let i=1;i<=m;i++) for(let j=1;j<=n;j++) d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1)); return d[m][n]; }
function sugerirComunaParecida(texto){
  const t=norm(texto||''); if(!t||t.length<4) return '';
  let mejor='',md=99;
  Object.keys(COMUNAS).forEach(function(c){ const d=_distEdicion(t,norm(c)); if(d<md){md=d;mejor=c;} });
  return md<=2 ? mejor : '';
}

function haversine(lon1,lat1,lon2,lat2){
  const R=6371;
  const p1=lat1*Math.PI/180, p2=lat2*Math.PI/180;
  const dphi=(lat2-lat1)*Math.PI/180, dlmb=(lon2-lon1)*Math.PI/180;
  const a=Math.sin(dphi/2)**2 + Math.cos(p1)*Math.cos(p2)*Math.sin(dlmb/2)**2;
  return 2*R*Math.asin(Math.sqrt(a));
}

function getComunaInfo(comuna){
  return COMUNAS[comunaKeyResuelta(comuna)] || null;
}

function coordFallbackComuna(s){
  const c = s && s._comunaInfo;
  if(c && Number.isFinite(c.lat) && Number.isFinite(c.lon)) return {lat:c.lat, lon:c.lon, exact:false, source:'comuna'};
  if(s && s.esOtraRegion){ const c2=getOtraRegionInfo(s.comuna); if(c2) return {lat:c2.lat,lon:c2.lon,exact:false,source:'comuna'}; }
  return null;
}

function coordStop(s){
  /* Coordenada válida solo si existe de verdad (null/''/undefined NO valen 0,0) y cae en la zona central de Chile. */
  if(s && s.lat!==null && s.lat!==undefined && s.lat!=='' && s.lon!==null && s.lon!==undefined && s.lon!=='' && Number.isFinite(Number(s.lat)) && Number.isFinite(Number(s.lon))){
    const la=Number(s.lat), lo=Number(s.lon);
    if(la>-35.5 && la<-32.0 && lo>-72.6 && lo<-69.0) return {lat:la,lon:lo,exact:s._geoExact===true,source:s._geoExact?'direccion':'comuna'};
  }
  return coordFallbackComuna(s);
}

function direccionBaseParaGeo(direccion){
  if(!direccion) return direccion;
  const m=String(direccion).match(/^(.*?\d+)\b/);
  return m ? m[1].trim() : direccion;
}

// "Ubicación imposible": caja que cubre la Región Metropolitana con un
// margen generoso. Cualquier coordenada que caiga afuera de esto (venga de
// Mapbox, de Nominatim, o de algo ya guardado en el caché) se descarta como
// si nunca hubiera llegado — esto existe porque Nominatim en particular
// puede matchear mal un nombre de calle genérico (ej. "El Quillay") con una
// calle del mismo nombre en otra región de Chile, a cientos de km, y sin
// este chequeo esa coordenada mala queda guardada en el caché para siempre.
const RM_BBOX = { latMin:-34.6, latMax:-32.5, lonMin:-71.8, lonMax:-69.8 };
function esUbicacionPlausibleRM(lat, lon){
  return Number.isFinite(lat) && Number.isFinite(lon)
    && lat>=RM_BBOX.latMin && lat<=RM_BBOX.latMax
    && lon>=RM_BBOX.lonMin && lon<=RM_BBOX.lonMax;
}

// Segundo filtro, más fino que el cajón de toda la Región Metropolitana: si
// el pedido ya tiene identificada su comuna (con su centro aproximado), una
// dirección geocodificada no debería caer a más de ~40km de ese centro. Esto
// agarra el caso típico de Nominatim/Mapbox matcheando mal un nombre de
// calle genérico con una calle del mismo nombre en OTRA comuna — que de otra
// forma pasaría el chequeo de "¿está dentro de la RM?" sin problema, porque
// la otra comuna también está dentro de la RM. 40km es generoso a propósito:
// hay comunas rurales grandes (Melipilla, San José de Maipo, Til Til) donde
// una punta a otra ya son varias decenas de km, así que preferimos ser
// permisivos antes que descartar una dirección real.
const RADIO_MAX_DESDE_COMUNA_KM = 40;
function esUbicacionPlausibleParaStop(s, lat, lon){
  if(!esUbicacionPlausibleRM(lat, lon)) return false;
  const c=s && s._comunaInfo;
  if(c && Number.isFinite(c.lat) && Number.isFinite(c.lon)){
    return haversine(lon, lat, c.lon, c.lat) <= RADIO_MAX_DESDE_COMUNA_KM;
  }
  return true; // sin comuna identificada todavía: nos quedamos solo con el chequeo de la RM
}

async function geocodificarUno(s, force){
  const key=geoKey(s.direccion,s.comuna);
  if(!force && geoCache[key] && esUbicacionPlausibleParaStop(s, geoCache[key].lat, geoCache[key].lon)){
    s.lat=geoCache[key].lat; s.lon=geoCache[key].lon; s._geoExact=true; s._geoSource='cache'; return {ok:true,network:true};
  }
  const direccionParaBuscar=direccionBaseParaGeo(s.direccion);

  // Primero se intenta con Mapbox (más preciso con direcciones con errores
  // de tipeo o abreviaciones raras). Si no hay token configurado, si se
  // llegó al límite seguro del mes, o si falla por cualquier motivo, esta
  // función devuelve null y seguimos con Nominatim exactamente como antes
  // — ningún comportamiento previo se pierde, Mapbox solo se suma arriba.
  const viaMapbox = await mapbox.geocodificarConMapbox(direccionParaBuscar, s.comuna);
  if (viaMapbox && esUbicacionPlausibleParaStop(s, viaMapbox.lat, viaMapbox.lon)) {
    s.lat=viaMapbox.lat; s.lon=viaMapbox.lon; s._geoExact=true; s._geoSource='mapbox';
    geoCache[key]={lat:s.lat,lon:s.lon,savedAt:Date.now()}; guardarGeoCache(); return {ok:true,network:true};
  }

  const query=encodeURIComponent((direccionParaBuscar||'')+', '+(s.comuna||'')+', Región Metropolitana, Chile');
  const ctrl=new AbortController(); const timer=setTimeout(function(){ctrl.abort();},9000);
  let networkOk=false;
  try{
    const resp=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=cl&addressdetails=1&q='+query,{headers:{'Accept-Language':'es-CL,es;q=0.9'},signal:ctrl.signal});
    if(!resp.ok) throw new Error('Nominatim HTTP '+resp.status);
    networkOk=true; // el servidor respondió: la red funciona, aunque no haya resultado para esta dirección puntual
    const data=await resp.json();
    const lat=data && data[0] && parseFloat(data[0].lat);
    const lon=data && data[0] && parseFloat(data[0].lon);
    if(esUbicacionPlausibleParaStop(s,lat,lon)){
      s.lat=lat; s.lon=lon; s._geoExact=true; s._geoSource='nominatim';
      geoCache[key]={lat:s.lat,lon:s.lon,savedAt:Date.now()}; guardarGeoCache(); return {ok:true,network:true};
    }
  }catch(e){ s._geoError=e && e.name==='AbortError' ? 'Tiempo de espera agotado' : (e.message||'Error de geocodificación'); }
  finally{ clearTimeout(timer); }
  const fb=coordFallbackComuna(s);
  if(fb){ s.lat=fb.lat; s.lon=fb.lon; s._geoExact=false; s._geoSource='comuna'; }
  return {ok:false,network:networkOk};
}

async function geocodificarStops(stops, forceKeys, onProgress){
  const lista=stops.filter(function(s){return s.direccion && s._comunaInfo;});
  let first=true;
  let fallasDeRedSeguidas=0;
  let redCortada=false;
  /* Si la geocodificación en línea (Nominatim) no responde varias veces seguidas,
     asumimos que la red está bloqueada/caída (típico en redes de bodega/empresa) y
     dejamos de intentarlo para el resto del lote: cada dirección nueva sin red
     costaba hasta ~10s (9s de espera + 1.1s de pausa) sin ningún beneficio, lo que
     podía dejar "Optimizar" pegado varios minutos con lotes grandes. Las paradas
     restantes usan directamente el centro de su comuna, igual que si hubiese fallado
     una por una, pero sin la espera. */
  for(let i=0;i<lista.length;i++){
    const s=lista[i];
    const key=geoKey(s.direccion,s.comuna);
    const force=forceKeys && forceKeys.has(key);
    const cached=!force && geoCache[key] && Number.isFinite(geoCache[key].lat);
    if(!force && cached){ await geocodificarUno(s,false); if(onProgress) onProgress(i+1,lista.length); continue; }
    if(redCortada){
      const fb=coordFallbackComuna(s);
      if(fb){ s.lat=fb.lat; s.lon=fb.lon; s._geoExact=false; s._geoSource='comuna'; s._geoError='Red no disponible: se usó el centro de la comuna'; }
      if(onProgress) onProgress(i+1,lista.length);
      continue;
    }
    if(!first) await sleep(1100); first=false;
    const r=await geocodificarUno(s,force);
    if(r.network){ fallasDeRedSeguidas=0; } else { fallasDeRedSeguidas++; if(fallasDeRedSeguidas>=3) redCortada=true; }
    if(onProgress) onProgress(i+1,lista.length);
  }
}

function geoKey(direccion, comuna){ return norm((direccion||'')+'|'+(comuna||'')); }

function sleep(ms){ return new Promise(function(resolve){setTimeout(resolve,ms);}); }

function getOtraRegionInfo(comuna){
  return OTRAS_REGIONES[norm(comuna)] || null;
}

function esOtraRegion(comuna){
  return !!getOtraRegionInfo(comuna);
}

function esRetiro(pedido){
  return /^600/.test(String(pedido||'').trim());
}

function esServicioFlete(p){
  // Lineas de "SERVICIO DE FLETE" / "SERVICIO FLETE" / "SERVICIO DE FLETE RM" (esta ultima
  // ya queda cubierta por "SERVICIO DE FLETE") son cobros de transporte que vienen mezclados
  // en el Excel, no productos reales a entregar. Se detectan SOLO por lo que dice la
  // descripcion del material — nunca deben entrar a la planificacion de rutas.
  const texto = ((p.descripcionMaterial||'') + ' ' + (p.producto||'')).toUpperCase();
  return texto.indexOf('SERVICIO DE FLETE') !== -1 || texto.indexOf('SERVICIO FLETE') !== -1;
}

function volCarga(s){
  // Volumen que realmente ocupa espacio al salir del deposito. Los retiros (pedidos que
  // empiezan con 600) se recogen al final de la ruta, asi que no cuentan para la capacidad
  // de carga inicial del camion, aunque igual se muestran y se visitan como cualquier parada.
  return s.esRetiro ? 0 : s.volumen;
}

function consolidar(pedidos){
  const map = new Map();
  for(const p of pedidos){
    if(esServicioFlete(p)) continue; // cobro de flete, no es un pedido real: nunca se planifica
    const key = norm(p.pedido);
    if(!map.has(key)){
      const esOtra = esOtraRegion(p.comuna);
      map.set(key, Object.assign({}, p, {
        volumen:0, esRetiro: esRetiro(p.pedido), esOtraRegion: esOtra,
        _comunaInfo: esOtra ? getOtraRegionInfo(p.comuna) : getComunaInfo(p.comuna)
      }));
    }
    map.get(key).volumen += Number(p.volumen)||0;
    if(!map.get(key)._lineas) map.get(key)._lineas=[];
    map.get(key)._lineas.push(p);
  }
  return Array.from(map.values());
}

function centroideStops(stopsArr){
  return {
    lon: stopsArr.reduce(function(a,s){const c=coordStop(s);return a+(c?c.lon:0);},0)/stopsArr.length,
    lat: stopsArr.reduce(function(a,s){const c=coordStop(s);return a+(c?c.lat:0);},0)/stopsArr.length
  };
}

function kmeansSplit(stops, n){
  if(n<=1 || stops.length<=1) return [stops];
  n = Math.min(n, stops.length);
  const seeds=[0];
  for(let i=1;i<n;i++){
    let best=-1,bestD=-1;
    for(let p=0;p<stops.length;p++){
      if(seeds.includes(p)) continue;
      let minD=Infinity;
      for(const s of seeds){
        const d=haversine(coordStop(stops[p]).lon,coordStop(stops[p]).lat,coordStop(stops[s]).lon,coordStop(stops[s]).lat);
        if(d<minD) minD=d;
      }
      if(minD>bestD){bestD=minD;best=p;}
    }
    seeds.push(best);
  }
  let centroids = seeds.map(function(i){return {lon:coordStop(stops[i]).lon, lat:coordStop(stops[i]).lat};});
  let assign = new Array(stops.length).fill(0);
  for(let iter=0; iter<20; iter++){
    let changed=false;
    for(let i=0;i<stops.length;i++){
      let best=0,bestD=Infinity;
      for(let c=0;c<n;c++){
        const d=haversine(coordStop(stops[i]).lon,coordStop(stops[i]).lat,centroids[c].lon,centroids[c].lat);
        if(d<bestD){bestD=d;best=c;}
      }
      if(assign[i]!==best){assign[i]=best;changed=true;}
    }
    const sums=Array.from({length:n},function(){return {lon:0,lat:0,cnt:0};});
    for(let i=0;i<stops.length;i++){const c=assign[i]; sums[c].lon+=stops[i]._comunaInfo.lon; sums[c].lat+=stops[i]._comunaInfo.lat; sums[c].cnt++;}
    centroids = sums.map(function(s,idx){ return s.cnt>0 ? {lon:s.lon/s.cnt, lat:s.lat/s.cnt} : centroids[idx]; });
    if(!changed) break;
  }
  const out = Array.from({length:n},function(){return [];});
  stops.forEach(function(s,i){ out[assign[i]].push(s); });
  return out.filter(function(g){return g.length>0;});
}

function rebalancearGruposPorComuna(partes, iteraciones, pesos){
  if(partes.length<2) return partes;
  const grupos = partes.map(function(p,i){ return {stops:p.slice(), volumen:p.reduce(function(a,s){return a+volCarga(s);},0), peso:(pesos&&pesos[i]>0)?pesos[i]:1}; });
  /* Macro-sector (A/B/C/D, via CORREDOR_PADRE) de un conjunto de paradas.
     Se usa para que el balanceo de volumen nunca vuelva a mezclar sectores
     opuestos (p.ej. Norte con Oriente/Santiago Centro) solo por parejar m³:
     eso es justo el "zigzag" reportado por el usuario. La fusión por macro
     (más arriba, antes de llamar a esta función) ya decide qué sectores
     conviven en cada grupo; este balanceo solo puede mover comunas cuyo
     macro-sector YA está presente en el grupo que recibe. */
  function macrosDe(stopsArr){
    const set=new Set();
    stopsArr.forEach(function(s){ const c=corredorOperativoDeStop(s); const p=c&&CORREDOR_PADRE[c]; if(p) set.add(p); });
    return set;
  }
  for(let it=0; it<iteraciones; it++){
    grupos.sort(function(a,b){return (b.volumen/b.peso)-(a.volumen/a.peso);});
    const peor = grupos[0], mejor = grupos[grupos.length-1];
    const ratioPeor=peor.volumen/peor.peso, ratioMejor=mejor.volumen/mejor.peso;
    if(peor===mejor || ratioPeor - ratioMejor < ratioPeor*0.08) break;
    if(peor.stops.length<=1) break;
    const porComuna={};
    peor.stops.forEach(function(s){ const k=norm(s.comuna); (porComuna[k]||(porComuna[k]=[])).push(s); });
    let comunas=Object.keys(porComuna);
    if(comunas.length<=1) break; // no queda otra comuna que mover sin vaciar el grupo
    const macrosDestino = macrosDe(mejor.stops);
    if(macrosDestino.size){
      comunas = comunas.filter(function(k){
        const bloque=porComuna[k];
        const c=corredorOperativoDeStop(bloque[0]);
        const p=c&&CORREDOR_PADRE[c];
        return !p || macrosDestino.has(p);
      });
    }
    if(!comunas.length) break; // ninguna comuna del grupo sobrecargado es compatible con el sector del destino
    const cDest = centroideStops(mejor.stops.length ? mejor.stops : peor.stops);
    let mejorComuna=null, mejorD=Infinity;
    comunas.forEach(function(k){
      const bloque=porComuna[k];
      const c=centroideStops(bloque);
      const d=haversine(c.lon,c.lat,cDest.lon,cDest.lat);
      if(d<mejorD){mejorD=d;mejorComuna=k;}
    });
    if(!mejorComuna) break;
    const bloque=porComuna[mejorComuna];
    const volBloque=bloque.reduce(function(a,s){return a+volCarga(s);},0);
    // No mover un bloque tan grande que solo invierta el desbalance (comparado
    // en la misma escala ponderada que se usa para decidir quién es "peor").
    const ratioTrasMover=(peor.volumen-volBloque)/peor.peso;
    const ratioMejorTrasRecibir=(mejor.volumen+volBloque)/mejor.peso;
    if(ratioTrasMover < ratioMejorTrasRecibir && volBloque/peor.peso>(ratioPeor-ratioMejor)) break;
    peor.stops = peor.stops.filter(function(s){return norm(s.comuna)!==mejorComuna;});
    peor.volumen -= volBloque;
    mejor.stops = mejor.stops.concat(bloque);
    mejor.volumen += volBloque;
  }
  return grupos.map(function(g){return g.stops;});
}

function rebalancearGrupo(partes, iteraciones){
  if(partes.length<2) return partes;
  const grupos = partes.map(function(p){ return {stops:p.slice(), volumen:p.reduce(function(a,s){return a+volCarga(s);},0)}; });
  for(let it=0; it<iteraciones; it++){
    grupos.sort(function(a,b){return b.volumen-a.volumen;});
    const peor = grupos[0], mejor = grupos[grupos.length-1];
    if(peor===mejor || peor.volumen - mejor.volumen < peor.volumen*0.08) break;
    if(peor.stops.length<=1) break;
    const cDest = centroideStops(mejor.stops.length ? mejor.stops : peor.stops);
    let bestIdx=-1,bestD=Infinity;
    peor.stops.forEach(function(s,i){
      const d=haversine(coordStop(s).lon,coordStop(s).lat,cDest.lon,cDest.lat);
      if(d<bestD){bestD=d;bestIdx=i;}
    });
    if(bestIdx===-1) break;
    const moved = peor.stops.splice(bestIdx,1)[0];
    peor.volumen -= volCarga(moved);
    mejor.stops.push(moved);
    mejor.volumen += volCarga(moved);
  }
  return grupos.map(function(g){return g.stops;});
}

function repartirCamiones(volPorZona, k){
  const zonas = Object.keys(volPorZona).filter(function(z){return volPorZona[z]>0;});
  const totalVol = zonas.reduce(function(a,z){return a+volPorZona[z];},0);
  if(zonas.length===0) return {};
  if(k < zonas.length) return null;
  const ideal = {};
  zonas.forEach(function(z){ ideal[z] = (volPorZona[z]/totalVol)*k; });
  let floors = {}; zonas.forEach(function(z){ floors[z] = Math.floor(ideal[z]); });
  let asignados = zonas.reduce(function(a,z){return a+floors[z];},0);
  let restante = k - asignados;
  const restos = zonas.map(function(z){return {z, resto: ideal[z]-floors[z]};}).sort(function(a,b){return b.resto-a.resto;});
  let idx=0;
  while(restante>0){ floors[restos[idx % restos.length].z]++; restante--; idx++; }
  let zonasEnCero = zonas.filter(function(z){return floors[z]===0;});
  let guard = 0;
  while(zonasEnCero.length>0 && guard<50){
    guard++;
    const candidatas = zonas.filter(function(z){return floors[z]>1;});
    if(candidatas.length===0) break;
    const zonaDonante = candidatas.sort(function(a,b){ return (floors[b]-ideal[b]) - (floors[a]-ideal[a]); })[0];
    floors[zonaDonante]--;
    floors[zonasEnCero[0]] = 1;
    zonasEnCero = zonas.filter(function(z){return floors[z]===0;});
  }
  return floors;
}

function ordenarPorCercania(stops){
  const pts=stops.map(function(s){const c=coordStop(s);return Object.assign({},s,c||{});});
  const visited=new Array(pts.length).fill(false), order=[];
  let curLon=DEPOT.lon, curLat=DEPOT.lat;
  for(let k=0;k<pts.length;k++){
    let best=-1,bestD=Infinity;
    for(let i=0;i<pts.length;i++){
      if(visited[i] || !Number.isFinite(pts[i].lon) || !Number.isFinite(pts[i].lat)) continue;
      const d=haversine(curLon,curLat,pts[i].lon,pts[i].lat);
      if(d<bestD){bestD=d;best=i;}
    }
    if(best<0) break;
    visited[best]=true;
    order.push(Object.assign({},pts[best],{distTramoKm:Math.round(bestD*10)/10}));
    curLon=pts[best].lon;curLat=pts[best].lat;
  }
  pts.forEach(function(s,i){if(!visited[i]) order.push(Object.assign({},s,{distTramoKm:0,_geoExact:false}));});
  return reordenarPorHorarios(order);
}

function reordenarPorHorarios(order){
  const posiciones = [];
  order.forEach(function(s,i){ if(s.horario) posiciones.push(i); });
  if(posiciones.length >= 2){
    const conHorario = posiciones.map(function(i){ return order[i]; });
    conHorario.sort(function(a,b){ return String(a.horario).localeCompare(String(b.horario)); });
    posiciones.forEach(function(pos, idx){ order[pos] = conHorario[idx]; });
    let curLon = DEPOT.lon, curLat = DEPOT.lat;
    order.forEach(function(s){
      const d = haversine(curLon, curLat, s.lon, s.lat);
      s.distTramoKm = Math.round(d*10)/10;
      curLon = s.lon; curLat = s.lat;
    });
  }
  return order;
}

function calcularDistanciaKm(p1,p2){
  const R=6371;
  const dLat=(p2.lat-p1.lat)*Math.PI/180;
  const dLon=(p2.lng-p1.lng)*Math.PI/180;
  const a=Math.sin(dLat/2)**2+
    Math.cos(p1.lat*Math.PI/180)*Math.cos(p2.lat*Math.PI/180)*Math.sin(dLon/2)**2;
  return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
}

function optimizarOrden2OptDesdeLampa(orden){
  if(orden.length<4) return orden;
  /* Si hay múltiples ventanas horarias, la secuencia temporal tiene prioridad. */
  if(orden.filter(function(s){return !!s.horario;}).length>=2) return orden;
  const puntos=[{lat:BASE_LAMPA.lat,lon:BASE_LAMPA.lng}].concat(orden.map(function(s){
    const c=coordStop(s); return c?{lat:c.lat,lon:c.lon}:null;
  })).filter(Boolean);
  if(puntos.length!==orden.length+1) return orden;
  /* Ambos puntos pueden venir como {lat,lon} (paradas/base): se normalizan a {lat,lng}.
     (Antes solo se normalizaba el segundo y el 2-opt comparaba NaN, así que casi nunca mejoraba nada.) */
  function d(a,b){return calcularDistanciaKm({lat:a.lat,lng:(a.lon!==undefined?a.lon:a.lng)},{lat:b.lat,lng:(b.lon!==undefined?b.lon:b.lng)});}
  let mejor=orden.slice();
  let mejorDist=0;
  for(let i=0;i<mejor.length;i++){
    const a=i===0?puntos[0]:{lat:mejor[i-1].lat,lon:mejor[i-1].lon};
    const b={lat:mejor[i].lat,lon:mejor[i].lon};
    mejorDist+=d(a,b);
  }
  const ult=mejor[mejor.length-1];
  mejorDist+=d({lat:ult.lat,lon:ult.lon},puntos[0]);
  let cambio=true, iter=0;
  while(cambio && iter<80){
    cambio=false; iter++;
    for(let i=0;i<mejor.length-1;i++){
      for(let k=i+1;k<mejor.length;k++){
        const A=i===0?puntos[0]:{lat:mejor[i-1].lat,lon:mejor[i-1].lon};
        const B={lat:mejor[i].lat,lon:mejor[i].lon};
        const C={lat:mejor[k].lat,lon:mejor[k].lon};
        const D=k===mejor.length-1?puntos[0]:{lat:mejor[k+1].lat,lon:mejor[k+1].lon};
        const actual=d(A,B)+d(C,D);
        const propuesta=d(A,C)+d(B,D);
        if(propuesta+1e-6<actual){
          const invertida=mejor.slice(i,k+1).reverse();
          mejor.splice.apply(mejor,[i,k-i+1].concat(invertida));
          cambio=true;
        }
      }
    }
  }
  return mejor;
}

function nearestNeighborBase(stops){
  const pts=stops.map(function(s){
    const c=coordStop(s);
    return Object.assign({},s,c?{lat:c.lat,lon:c.lon}:{lat:null,lon:null});
  });
  const pendientes=pts.filter(function(s){return Number.isFinite(s.lat)&&Number.isFinite(s.lon);});
  const sinCoord=pts.filter(function(s){return !Number.isFinite(s.lat)||!Number.isFinite(s.lon);});
  const orden=[];
  let actual={lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng};

  while(pendientes.length){
    let bestIdx=-1,bestScore=Infinity,bestDist=Infinity;
    for(let i=0;i<pendientes.length;i++){
      const p=pendientes[i];
      const d=calcularDistanciaKm(actual,{lat:p.lat,lng:p.lon});
      /* Penalización pequeña por invertir bruscamente el eje longitudinal respecto de Lampa.
         Es un desempate suave: la proximidad geográfica sigue siendo la regla principal. */
      const retroceso = orden.length && ((p.lon-actual.lng)*(actual.lng-BASE_LAMPA.lng)<0) ? 0.15 : 0;
      const score=d+retroceso;
      if(score<bestScore || (Math.abs(score-bestScore)<1e-9 && d<bestDist)){
        bestScore=score; bestDist=d; bestIdx=i;
      }
    }
    if(bestIdx<0) break;
    const next=pendientes.splice(bestIdx,1)[0];
    orden.push(Object.assign({},next,{distTramoKm:Math.round(bestDist*10)/10}));
    actual={lat:next.lat,lng:next.lon};
  }
  const optimizada=optimizarOrden2OptDesdeLampa(orden);
  sinCoord.forEach(function(s){ optimizada.push(Object.assign({},s,{distTramoKm:0,_geoExact:false})); });
  let cur={lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng};
  optimizada.forEach(function(s){
    const c=coordStop(s);
    if(c){s.distTramoKm=Math.round(calcularDistanciaKm(cur,{lat:c.lat,lng:c.lon})*10)/10;cur={lat:c.lat,lng:c.lon};}
    else s.distTramoKm=0;
  });
  return optimizada;
}


/* Clave de "misma dirección": calle + número (sin pisos/locales) + comuna. */
function claveDireccionStop(s){
  return norm(direccionBaseParaGeo(s.direccion)||'')+'|'+norm(comunaKeyResuelta(s.comuna));
}

/* Orden de visita con regla de RETIROS: los pedidos que empiezan con 600 se
   visitan DESPUÉS de las entregas. Única excepción operativa: un retiro cuya
   dirección es la misma de una entrega de la ruta se hace justo después de la
   última entrega de esa dirección (el camión ya está ahí; volver después
   costaría un retroceso entero sin ningún beneficio). El resto de los retiros
   va al final, ordenados por cercanía. */
function nearestNeighborDesdeLampa(stops){
  const entregas=stops.filter(function(s){return !s.esRetiro;});
  const retiros=stops.filter(function(s){return s.esRetiro;});
  if(!entregas.length || !retiros.length) return nearestNeighborBase(stops);
  const ordEnt=nearestNeighborBase(entregas);
  const ultimoIdx=new Map();
  ordEnt.forEach(function(s,i){ ultimoIdx.set(claveDireccionStop(s), i); });
  const anclados=new Map(); const libres=[];
  retiros.forEach(function(r){
    const k=claveDireccionStop(r);
    if(ultimoIdx.has(k)){ const i=ultimoIdx.get(k); (anclados.get(i)||anclados.set(i,[]).get(i)).push(r); }
    else libres.push(r);
  });
  const orden=[];
  ordEnt.forEach(function(s,i){
    orden.push(s);
    (anclados.get(i)||[]).forEach(function(r){
      const c=coordStop(r);
      orden.push(Object.assign({},r,c?{lat:c.lat,lon:c.lon}:{}, {_retiroEnMismaDireccion:true}));
    });
  });
  // Retiros restantes: al final, siempre el más cercano al punto actual.
  const pend=libres.map(function(r){const c=coordStop(r);return Object.assign({},r,c?{lat:c.lat,lon:c.lon}:{lat:null,lon:null});});
  while(pend.length){
    const ult=orden[orden.length-1];
    let bi=0,bd=Infinity;
    pend.forEach(function(p,i){
      const d=(Number.isFinite(p.lat)&&Number.isFinite(ult.lat))?calcularDistanciaKm({lat:ult.lat,lng:ult.lon},{lat:p.lat,lng:p.lon}):0;
      if(d<bd){bd=d;bi=i;}
    });
    orden.push(pend.splice(bi,1)[0]);
  }
  let cur={lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng};
  orden.forEach(function(s){
    const c=coordStop(s);
    if(c){s.distTramoKm=Math.round(calcularDistanciaKm(cur,{lat:c.lat,lng:c.lon})*10)/10;cur={lat:c.lat,lng:c.lon};}
    else s.distTramoKm=0;
  });
  return orden;
}

function distanciaRutaNN(stops){
  let total=0;
  let actual={lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng};
  stops.forEach(function(s){
    const c=coordStop(s);
    if(!c) return;
    total+=calcularDistanciaKm(actual,{lat:c.lat,lng:c.lon});
    actual={lat:c.lat,lng:c.lon};
  });
  if(stops.length){
    const last=coordStop(stops[stops.length-1]);
    if(last) total+=calcularDistanciaKm(actual,{lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng});
  }
  return Math.round(total*FACTOR_DESVIO_VIAL*10)/10;
}

/* Guardarraíl contra "distancias imposibles": una ruta que reparte DENTRO de
   la Región Metropolitana, con 20-25 paradas como mucho, nunca debería dar
   varios cientos de km reales. Si una fuente externa (OSRM o Mapbox) dice lo
   contrario, es mucho más probable que una dirección esté mal geocodificada
   (match equivocado a otra ciudad/comuna lejana) que que la ruta sea así de
   larga en realidad. En ese caso, se descarta ese número y se mantiene la
   estimación de línea recta de siempre — igual que ya se hace cuando Mapbox
   no responde. Esto protege sin importar POR QUÉ vino mal el dato. */
const DISTANCIA_MAX_PLAUSIBLE_RM_KM = 220;
function esDistanciaPlausible(distKm, estimadoBaseKm){
  if(!Number.isFinite(distKm) || distKm<=0) return false;
  if(distKm > DISTANCIA_MAX_PLAUSIBLE_RM_KM) return false;
  if(Number.isFinite(estimadoBaseKm) && estimadoBaseKm>0 && distKm > estimadoBaseKm*3) return false;
  return true;
}

/* Afina el ORDEN de las paradas de una ruta YA armada, usando distancia real
   de calle (OSRM, gratis) en vez de línea recta. Se usa una sola vez por
   ruta, al final — nunca dentro del algoritmo que arma/rebalancea las rutas
   (ese sigue con línea recta, que es instantánea). Si OSRM no responde, o el
   resultado es una distancia imposible (ver esDistanciaPlausible), no cambia
   nada: se queda el orden que ya había calculado nearestNeighborDesdeLampa. */
async function refinarOrdenConOSRM(r, estimadoBaseKm){
  if(!r.stopsOrdenados || r.stopsOrdenados.length<3) return;
  const stops=r.stopsOrdenados;
  const conCoord=stops.every(function(s){return Number.isFinite(s.lat)&&Number.isFinite(s.lon);});
  if(!conCoord) return; // si falta alguna coordenada, no se arriesga el orden
  const puntos=[{lat:BASE_LAMPA.lat,lon:BASE_LAMPA.lng}].concat(stops.map(function(s){return {lat:s.lat,lon:s.lon};}));
  const matriz=await osrm.obtenerMatrizOSRM(puntos);
  if(!matriz) return;
  const idxActual=stops.map(function(_,i){return i+1;});
  const idxOptimo=osrm.twoOptConMatriz(idxActual,matriz);
  let anterior=0, totalKm=0;
  idxOptimo.forEach(function(actual){
    totalKm+=matriz[anterior][actual]/1000;
    anterior=actual;
  });
  totalKm+=matriz[anterior][0]/1000; // vuelta a la base
  if(!esDistanciaPlausible(totalKm, estimadoBaseKm)) return; // dato imposible: se descarta entero (orden incluido)
  const nuevoOrden=idxOptimo.map(function(i){return stops[i-1];});
  anterior=0;
  nuevoOrden.forEach(function(s,pos){
    const actual=idxOptimo[pos];
    s.distTramoKm=Math.round((matriz[anterior][actual]/1000)*10)/10;
    anterior=actual;
  });
  r.stopsOrdenados=nuevoOrden;
  r.distTotalKm=Math.round(totalKm*10)/10;
  r._ordenFuente='osrm';
  r._distanciaFuente='osrm';
}

function capacidadEfectivaDosVueltas(camion){
  return Math.max(0, Number(camion && camion.mts3) || 0) * MAX_VUELTAS_POR_CAMION;
}

function asignarCamionesPorSector(volPorZona, fleet){
  const zonas=Object.keys(volPorZona).filter(function(z){return Number(volPorZona[z])>0;})
    .sort(function(a,b){return volPorZona[b]-volPorZona[a];});
  const disponibles=fleet.slice();
  const asignacion={};
  zonas.forEach(function(z){asignacion[z]=[];});
  if(!zonas.length || !disponibles.length) return asignacion;

  function elegirParaZona(volumen, pool){
    if(!pool.length) return null;
    const candidatos=pool.map(function(f){
      const cap=Number(f.mts3)||0;
      const viajesNecesarios = cap>0 ? Math.ceil(volumen/cap) : Infinity;
      const cubreEnDos = volumen <= capacidadEfectivaDosVueltas(f)+1e-9;
      return {f:f,cap:cap,viajes:viajesNecesarios,cubreEnDos:cubreEnDos};
    }).filter(function(x){return x.cap>0;});
    candidatos.sort(function(a,b){
      if(a.cubreEnDos!==b.cubreEnDos) return a.cubreEnDos ? -1 : 1;
      if(a.viajes!==b.viajes) return a.viajes-b.viajes;
      return a.cap-b.cap;
    });
    return candidatos.length ? candidatos[0].f : null;
  }

  /* Garantiza un camión por corredor mientras haya flota. */
  zonas.forEach(function(z){
    if(!disponibles.length) return;
    const elegido=elegirParaZona(volPorZona[z],disponibles);
    if(elegido){
      asignacion[z].push(elegido);
      disponibles.splice(disponibles.indexOf(elegido),1);
    }
  });

  /* Agrega camiones únicamente cuando el corredor necesita más capacidad que
     la suma de dos vueltas de los camiones que ya tiene asignados. */
  while(disponibles.length){
    let deficitZona=null, deficit=-Infinity;
    zonas.forEach(function(z){
      const capacidad2=asignacion[z].reduce(function(a,f){return a+capacidadEfectivaDosVueltas(f);},0);
      const d=Number(volPorZona[z])-capacidad2;
      if(d>deficit){deficit=d;deficitZona=z;}
    });
    if(!deficitZona || deficit<=1e-9) break;

    disponibles.sort(function(a,b){
      const ca=Number(a.mts3)||0, cb=Number(b.mts3)||0;
      /* Preferimos la menor capacidad que resuelva el déficit. */
      const sa=ca>=deficit/2 ? ca : Infinity;
      const sb=cb>=deficit/2 ? cb : Infinity;
      if(sa!==sb) return sa-sb;
      return ca-cb;
    });
    const elegido=disponibles.shift();
    if(!elegido) break;
    asignacion[deficitZona].push(elegido);
  }
  return asignacion;
}

function particionarSectorNN(stops, camiones){
  /*
   * REV18 — Empaquetado por capacidad + continuidad geográfica.
   *
   * El problema de la versión anterior era que repartía las paradas de forma
   * demasiado secuencial. Eso podía dejar, por ejemplo, 1.2 m³ pendientes en
   * una vuelta aunque otra combinación de pedidos sí cupiera.
   *
   * Aquí cada patente dispone de DOS "slots" como máximo:
   *   - vuelta 1
   *   - vuelta 2
   *
   * Se hace bin-packing descendente por volumen (los pedidos grandes primero),
   * pero el costo de asignación también considera continuidad geográfica y la
   * meta 65% como objetivo blando. La capacidad física sigue siendo el límite
   * duro. Así llegar a la meta NO expulsa pedidos: simplemente hace que el
   * siguiente pedido prefiera otra vuelta disponible.
   */
  const EPS=1e-9;
  if(!Array.isArray(camiones) || !camiones.length) return {grupos:[],sinCamion:stops.slice()};

  const orden=nearestNeighborDesdeLampa(stops);
  const slots=[];
  camiones.forEach(function(f){
    const cap=Math.max(0,Number(f.mts3)||0);
    if(cap<=EPS) return;
    slots.push({camion:f,vueltaNumero:1,tipoVuelta:'PRIMERA VUELTA',stops:[],volumen:0,cap:cap});
    slots.push({camion:f,vueltaNumero:2,tipoVuelta:'SEGUNDA VUELTA',stops:[],volumen:0,cap:cap});
  });

  function coord(s){ return coordStop(s); }
  function dist(a,b){
    const ca=coord(a), cb=coord(b);
    if(!ca || !cb) return 9999;
    return calcularDistanciaKm({lat:ca.lat,lng:ca.lon},{lat:cb.lat,lng:cb.lon});
  }
  function puede(slot,s){
    const v=volCarga(s);
    return Number.isFinite(v) && v>=0;
  }
  function distanciaAlSlot(slot,s){
    if(!slot.stops.length){
      const c=coord(s);
      return c ? calcularDistanciaKm(BASE_LAMPA,{lat:c.lat,lng:c.lon}) : 9999;
    }
    /* Usar la distancia al punto más cercano del grupo es más estable que usar
       solo la última parada, especialmente cuando el pedido grande se inserta
       en una ruta que ya tiene varias paradas. */
    let best=Infinity;
    slot.stops.forEach(function(x){ best=Math.min(best,dist(x,s)); });
    return best;
  }
  function centroideSlot(slot){
    if(!slot.stops.length) return {lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng};
    const pts=slot.stops.map(coord).filter(Boolean);
    if(!pts.length) return {lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng};
    return {lat:pts.reduce(function(a,c){return a+c.lat;},0)/pts.length,
            lng:pts.reduce(function(a,c){return a+c.lon;},0)/pts.length};
  }
  function scoreSlot(slot,s){
    const v=volCarga(s);
    const after=slot.volumen+v;
    const cap=slot.cap;
    const utilBefore=cap>0?slot.volumen/cap:1;
    const distGeo=distanciaAlSlot(slot,s);
    const c=coord(s);
    const cent=centroideSlot(slot);
    const distCent=c?calcularDistanciaKm({lat:c.lat,lng:c.lon},cent):9999;
    const isSecond=slot.vueltaNumero===2;
    const first=slots.find(function(x){return x.camion.patente===slot.camion.patente && x.vueltaNumero===1;});
    const firstEmpty=first && !first.stops.length;
    /* Penalización suave: primero se intenta llenar la 1ª vuelta y mantenerla
       cerca de la meta; la 2ª se abre cuando realmente aporta capacidad.
       IMPORTANTE: ya NO hay penalización por pasar la meta (65%) ni por
       utilización alta — el usuario pidió explícitamente que no haya
       "bloqueo de carga por porcentaje": la 1ª vuelta se llena hasta su
       capacidad FÍSICA (mts3, el único límite duro, aplicado más abajo al
       elegir candidatos) y solo lo que ya no cabe pasa a la 2ª vuelta. La
       meta sigue mostrándose en pantalla como referencia informativa, pero
       no dirige el armado de las rutas. */
    const fragmentationPenalty=Math.max(0,cap-after)*0.015;
    /* Bonus por continuidad de comuna: si el destino ya tiene paradas de la
       misma comuna, se prefiere fuertemente mantenerlas juntas en la misma
       vuelta en vez de separarlas por un empate o casi-empate de distancia
       (esto es justo lo que pidió el usuario: "que queden bien ubicadas las
       optimizaciones de comuna y direcciones"). */
    const comunaStop=norm(s.comuna);
    const yaTieneComuna=slot.stops.some(function(x){return norm(x.comuna)===comunaStop;});
    const comunaBonus=yaTieneComuna ? -8 : 0;
    const secondPenalty=isSecond ? (firstEmpty ? 35 : 5) : 0;
    return distGeo*1.6 + distCent*0.35 + secondPenalty + fragmentationPenalty + comunaBonus - utilBefore*0.15;
  }

  /* Pedidos grandes primero: evita que los pequeños "fragmenten" la capacidad
     y luego impidan acomodar un pedido grande en la segunda vuelta. */
  const pendientes=orden.slice().sort(function(a,b){
    const dv=volCarga(b)-volCarga(a);
    if(Math.abs(dv)>EPS) return dv;
    return (Number(a.pedido)||0)-(Number(b.pedido)||0);
  });

  const noAsignados=[];
  pendientes.forEach(function(s){
    const candidatos=slots.slice();
    candidatos.sort(function(a,b){
      const af=(a.volumen+volCarga(s)<=a.cap+EPS)?0:1;
      const bf=(b.volumen+volCarga(s)<=b.cap+EPS)?0:1;
      if(af!==bf) return af-bf;
      return scoreSlot(a,s)-scoreSlot(b,s);
    });
    const elegido=candidatos[0];
    elegido.stops.push(s);
    elegido.volumen+=volCarga(s);
    if(elegido.volumen>elegido.cap+EPS) elegido.sobrecarga=true;
  });

  /* Cobertura total: no se descartan pedidos por capacidad. */

  /* Mejora local: si dos pedidos pueden intercambiarse entre vueltas sin
     superar capacidad y reducen la suma de distancias, se hace el intercambio.
     Solo afecta rutas del mismo corredor. */
  for(let iter=0;iter<35;iter++){
    let mejor=null;
    for(let a=0;a<slots.length;a++){
      for(let b=a+1;b<slots.length;b++){
        const A=slots[a],B=slots[b];
        if(A.camion.patente===B.camion.patente && A.vueltaNumero===B.vueltaNumero) continue;
        for(let ia=0;ia<A.stops.length;ia++){
          const sa=A.stops[ia], va=volCarga(sa);
          for(let ib=0;ib<B.stops.length;ib++){
            const sb=B.stops[ib], vb=volCarga(sb);
            if(A.volumen-va+vb>A.cap+EPS || B.volumen-vb+va>B.cap+EPS) continue;
            const antes=distanciaRutaNN(A.stops)+distanciaRutaNN(B.stops);
            const na=A.stops.slice(); na[ia]=sb;
            const nb=B.stops.slice(); nb[ib]=sa;
            const despues=distanciaRutaNN(na)+distanciaRutaNN(nb);
            const mejora=antes-despues;
            if(mejora>0.7 && (!mejor || mejora>mejor.mejora)) mejor={A:A,B:B,ia:ia,ib:ib,sA:sa,sB:sb,mejora:mejora};
          }
        }
      }
    }
    if(!mejor) break;
    mejor.A.stops[mejor.ia]=mejor.sB;
    mejor.B.stops[mejor.ib]=mejor.sA;
    mejor.A.volumen=mejor.A.stops.reduce(function(x,s){return x+volCarga(s);},0);
    mejor.B.volumen=mejor.B.stops.reduce(function(x,s){return x+volCarga(s);},0);
  }

  /* NOTA: antes había un paso extra que "balanceaba" el volumen entre la 1ª y
     la 2ª vuelta de un mismo camión moviendo paradas solo por porcentaje de
     carga, sin mirar la comuna — eso era exactamente lo que partía una misma
     comuna (p.ej. Huechuraba) entre dos rutas/vueltas distintas del mismo
     camión aunque cupieran juntas. El usuario pidió explícitamente que NO
     haya bloqueo ni reordenamiento por porcentaje: la 1ª vuelta se llena
     hasta su capacidad física (mts3) manteniendo las comunas agrupadas
     (bin-packing + bonus de continuidad de comuna más arriba), y si algo no
     alcanza a entrar pasa a la 2ª vuelta para que el usuario la revise y
     ajuste manualmente con "Mover a" si lo prefiere. Por eso este paso de
     balanceo por porcentaje se eliminó a propósito. */

  const grupos=slots.filter(function(g){return g.stops.length>0;}).map(function(g){
    g.stops=nearestNeighborDesdeLampa(g.stops);
    g.volumen=g.stops.reduce(function(a,s){return a+volCarga(s);},0);
    return g;
  });

  return {grupos:grupos,sinCamion:noAsignados};
}

function rebalancearExcedentesCorredor(rutasCorredor){
  if(!Array.isArray(rutasCorredor) || rutasCorredor.length<2) return 0;
  let movimientos=0;
  for(let iter=0;iter<120;iter++){
    let mejor=null;
    rutasCorredor.forEach(function(origen,oi){
      if(!origen.patente || origen.vueltaNumero>MAX_VUELTAS_POR_CAMION) return;
      origen.stops.forEach(function(st,si){
        rutasCorredor.forEach(function(destino,di){
          if(oi===di || !destino.patente || destino.vueltaNumero>MAX_VUELTAS_POR_CAMION) return;
          const v=volCarga(st);
          if(v>Number(destino.mts3)+1e-9 || Number(destino.volumen)+v>Number(destino.mts3)+1e-9) return;
          const antes=distanciaRutaNN(origen.stops)+distanciaRutaNN(destino.stops);
          const o2=origen.stops.filter(function(x,j){return j!==si;});
          const d2=destino.stops.concat([st]);
          const despues=distanciaRutaNN(o2)+distanciaRutaNN(d2);
          const mejora=antes-despues;
          const excesoOrigen=Math.max(0,Number(origen.volumen)-Number(origen.meta||origen.mts3));
          const prioridad=mejora + Math.min(excesoOrigen,10)*0.05;
          if(mejora>0.5 && (!mejor || prioridad>mejor.prioridad)){
            mejor={origen:origen,destino:destino,si:si,st:st,prioridad:prioridad};
          }
        });
      });
    });
    if(!mejor) break;
    mejor.origen.stops.splice(mejor.si,1);
    mejor.origen.volumen-=volCarga(mejor.st);
    mejor.destino.stops.push(mejor.st);
    mejor.destino.volumen+=volCarga(mejor.st);
    recalcularRuta(mejor.origen);
    recalcularRuta(mejor.destino);
    movimientos++;
  }
  return movimientos;
}

function recalcularRuta(r){
  r.volumen = r.stops.reduce(function(a,s){return a+volCarga(s);},0);
  r.volumenRetiro = r.stops.filter(function(s){return s.esRetiro;}).reduce(function(a,s){return a+s.volumen;},0);
  r.stopsOrdenados = r.stops.length ? nearestNeighborDesdeLampa(r.stops) : [];
  r.distTotalKm = distanciaRutaNN(r.stopsOrdenados);
  r.estado = calcularEstadoRuta(r);
}


/* ======================================================================
   OPTIMIZADOR GEOGRÁFICO GLOBAL
   Después de armar las rutas por corredor, revisa TODAS las rutas juntas y
   busca mejorarlas moviendo e intercambiando pedidos entre camiones, y
   cerrando rutas que no se justifican. Reglas (en orden de prioridad):
     1. Nunca separa un pedido; los pedidos con la misma dirección viajan
        siempre juntos (se mueven como un solo bloque).
     2. Coherencia geográfica / menor distancia / sin cruces ni retrocesos.
     3. Capacidad: tope duro 100% de la capacidad física; la meta del 70% es
        solo una referencia (penalización suave por pasarse, ninguna por
        quedar debajo: la geografía gana sobre el llenado).
   ====================================================================== */
const OPT_FIJO_POR_RUTA_KM = 22;      // costo equivalente de sacar una vuelta más
const OPT_PENAL_SOBRE_META_KM_M3 = 3; // km-equivalentes por m³ sobre el 70%
const OPT_PENAL_CRUCE_KM = 15;        // por cada cruce de la ruta consigo misma
const OPT_PENAL_MACRO_KM = 20;        // por cada macro-sector extra mezclado
const OPT_PENAL_SEGUNDA_VUELTA_KM = 30; // una 2ª vuelta cuesta más que usar una patente elegida que está libre
const OPT_PENAL_PERIFERICO_MEZCLA_KM = 120; // zonas lejanas (Peñaflor, Talagante, Melipilla…) no se mezclan con el resto: viaje propio o 2ª vuelta
const OPT_MAX_MIN_RUTA = 540;          // tope blando de 9 h por viaje (conducción a 22 km/h + 12 min por parada)
const OPT_PENAL_MIN_EXTRA_KM = 0.6;    // km-equivalentes por minuto sobre el tope
const OPT_PENAL_CORREDOR_KM = 25;     // por cada corredor extra mezclado en una misma ruta
const OPT_PENAL_DISPERSION_KM = 1.2;  // por km de distancia media de las paradas al centro de la ruta (compacidad)
const OPT_DIAMETRO_LIBRE_KM = 22;     // una ruta compacta no pasa de ~18 km entre sus puntos más lejanos
const OPT_PENAL_DIAMETRO_KM = 5.0;    // km-equivalentes por cada km de más
const OPT_PRESUPUESTO_MS = 4000;

function _rng(seed){ let a=seed>>>0; return function(){ a|=0; a=a+0x6D2B79F5|0; let t=Math.imul(a^a>>>15,1|a); t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }

function _cruces(orden){
  const pts=[{x:BASE_LAMPA.lng,y:BASE_LAMPA.lat}];
  orden.forEach(function(s){ const c=coordStop(s); if(!c) return; const p={x:c.lon,y:c.lat}; const q=pts[pts.length-1]; if(Math.abs(p.x-q.x)>1e-5||Math.abs(p.y-q.y)>1e-5) pts.push(p); });
  pts.push({x:BASE_LAMPA.lng,y:BASE_LAMPA.lat});
  function ccw(a,b,c){ return (c.y-a.y)*(b.x-a.x)-(b.y-a.y)*(c.x-a.x); }
  function inter(a,b,c,d){ const d1=ccw(a,b,c),d2=ccw(a,b,d),d3=ccw(c,d,a),d4=ccw(c,d,b); return ((d1>0)!==(d2>0)) && ((d3>0)!==(d4>0)) && d1!==0 && d2!==0 && d3!==0 && d4!==0; }
  let n=0;
  for(let i=0;i<pts.length-1;i++) for(let j=i+2;j<pts.length-1;j++){
    if(i===0 && j===pts.length-2) continue; // primer y último tramo comparten la base
    if(inter(pts[i],pts[i+1],pts[j],pts[j+1])) n++;
  }
  return n;
}

function optimizarGlobalRutas(rutas, fleetDisponible){
  const t0=Date.now();
  const rutasRM=rutas.filter(function(r){ return r.stops && r.stops.length && r.zonaCodigo!=='EXT'; });
  if(!rutasRM.length || !fleetDisponible || !fleetDisponible.length) return null;

  // --- Bloques indivisibles: mismo pedido = 1 parada; misma dirección = 1 bloque ---
  let unidades=[]; const porClave=new Map();
  const origenDe={}; // pedido -> etiqueta de ruta original
  rutasRM.forEach(function(r){
    const et=(r.patente||'SIN CAMIÓN')+' V'+(r.vueltaNumero||1);
    r.stops.forEach(function(s){
      origenDe[norm(s.pedido)]=et;
      const k=claveDireccionStop(s);
      if(!porClave.has(k)){ const u={id:unidades.length,stops:[],vol:0,key:k}; porClave.set(k,u); unidades.push(u); }
      const u=porClave.get(k); u.stops.push(s); u.vol+=volCarga(s);
    });
  });

  // --- Espacios disponibles (camión × vuelta). Se usan primero los camiones ya asignados. ---
  const usados=[]; rutasRM.forEach(function(r){ if(r.patente && usados.indexOf(r.patente)<0) usados.push(r.patente); });
  const camiones=[]; usados.forEach(function(p){ const f=fleetDisponible.find(function(x){return x.patente===p;}); if(f) camiones.push(f); });
  fleetDisponible.slice().sort(function(a,b){return b.mts3-a.mts3;}).forEach(function(f){ if(camiones.length<Math.min(12,fleetDisponible.length) && camiones.indexOf(f)<0) camiones.push(f); });
  const slots=[];
  camiones.forEach(function(f){ for(let v=1; v<=MAX_VUELTAS_POR_CAMION; v++) slots.push({camion:f,vuelta:v,cap:f.mts3,meta:f.meta}); });
  const maxCap=Math.max.apply(null,slots.map(function(s){return s.cap;}));
  /* Un bloque que por sí solo supera la capacidad de cualquier camión elegido
     (p.ej. un pedido de 45 m³) no se puede "optimizar": se saca del cálculo y,
     al final, se carga en la ruta de su sector (aunque la deje sobrecargada). */
  const grandes=unidades.filter(function(u){return u.vol>maxCap+1e-9;});
  if(grandes.length){ unidades=unidades.filter(function(u){return u.vol<=maxCap+1e-9;}); unidades.forEach(function(u,i){u.id=i;}); grandes.forEach(function(g){g.id=-1;}); }
  if(!unidades.length) return null;

  // Matrices de distancia entre bloques (una sola vez) para evaluar rutas rápido.
  const nU=unidades.length;
  unidades.forEach(function(u){ const c=coordStop(u.stops[0])||{lat:BASE_LAMPA.lat,lon:BASE_LAMPA.lng}; u.lat=c.lat; u.lon=c.lon; u.macro=zonaOperativaDeStop(u.stops[0])||'?'; u.corr=corredorOperativoDeStop(u.stops[0])||'?'; });
  const dep=unidades.map(function(u){return calcularDistanciaKm({lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng},{lat:u.lat,lng:u.lon});});
  const DM=unidades.map(function(a){return unidades.map(function(b){return calcularDistanciaKm({lat:a.lat,lng:a.lon},{lat:b.lat,lng:b.lon});});});
  function ordenRapido(ids){
    const n=ids.length; if(n===1) return {ord:ids.slice(),km:2*dep[ids[0]]*FACTOR_DESVIO_VIAL};
    const pend=ids.slice(); const ord=[]; let cur=-1;
    while(pend.length){ let bi=0,bd=Infinity; for(let i=0;i<pend.length;i++){ const d=cur<0?dep[pend[i]]:DM[cur][pend[i]]; if(d<bd){bd=d;bi=i;} } cur=pend.splice(bi,1)[0]; ord.push(cur); }
    const d=function(a,b){ return a<0?dep[b]:(b<0?dep[a]:DM[a][b]); };
    let mejora=true,it=0;
    while(mejora && it<30){ mejora=false; it++;
      for(let i=0;i<n-1;i++) for(let k=i+1;k<n;k++){
        const A=i===0?-1:ord[i-1],B=ord[i],C=ord[k],D=k===n-1?-1:ord[k+1];
        if(d(A,C)+d(B,D)+1e-9<d(A,B)+d(C,D)){ const seg=ord.slice(i,k+1).reverse(); for(let q=0;q<seg.length;q++) ord[i+q]=seg[q]; mejora=true; }
      }
    }
    let km=0,prev=-1; ord.forEach(function(x){ km+=d(prev,x); prev=x; }); km+=d(prev,-1);
    return {ord:ord,km:km*FACTOR_DESVIO_VIAL};
  }
  function crucesIds(ord){ return _cruces(ord.map(function(id){return {lat:unidades[id].lat,lon:unidades[id].lon};})); }

  const cache=new Map();
  function costoSlot(si,ids){
    if(!ids.length) return 0;
    const key=si+':'+ids.slice().sort(function(a,b){return a-b;}).join(',');
    let v=cache.get(key); if(v!==undefined) return v;
    let vol=0; ids.forEach(function(id){ vol+=unidades[id].vol; });
    const orr=ordenRapido(ids);
    let c=orr.km+OPT_FIJO_POR_RUTA_KM+OPT_PENAL_CRUCE_KM*crucesIds(orr.ord);
    const sl=slots[si];
    if(sl.vuelta>=2) c+=OPT_PENAL_SEGUNDA_VUELTA_KM; // se prefiere usar otra patente elegida antes que hacer una 2ª vuelta
    if(vol>sl.cap+1e-9) c+=1000+1000*(vol-sl.cap);
    else if(vol>sl.meta+1e-9) c+=OPT_PENAL_SOBRE_META_KM_M3*(vol-sl.meta);
    const macros=new Set(ids.map(function(id){return unidades[id].macro;})).size;
    c+=OPT_PENAL_MACRO_KM*(macros-1);
    const corrs=new Set(ids.map(function(id){return unidades[id].corr;})).size;
    const nPeri=ids.filter(function(id){return unidades[id].corr==='D_PERIFERICO';}).length;
    if(nPeri>0 && nPeri<ids.length) c+=OPT_PENAL_PERIFERICO_MEZCLA_KM;
    let nParadas=0; ids.forEach(function(id){ nParadas+=unidades[id].stops.length; });
    const minEst=(orr.km/22)*60+nParadas*12;
    if(minEst>OPT_MAX_MIN_RUTA) c+=OPT_PENAL_MIN_EXTRA_KM*(minEst-OPT_MAX_MIN_RUTA);
    c+=OPT_PENAL_CORREDOR_KM*(corrs-1);
    if(ids.length>1){ let cl=0,cn=0; ids.forEach(function(id){cl+=unidades[id].lat;cn+=unidades[id].lon;}); cl/=ids.length; cn/=ids.length;
      let disp=0; ids.forEach(function(id){ disp+=calcularDistanciaKm({lat:cl,lng:cn},{lat:unidades[id].lat,lng:unidades[id].lon}); });
      c+=OPT_PENAL_DISPERSION_KM*disp; }
    let diam=0; for(let i=0;i<ids.length;i++) for(let j=i+1;j<ids.length;j++){ if(DM[ids[i]][ids[j]]>diam) diam=DM[ids[i]][ids[j]]; }
    if(diam>OPT_DIAMETRO_LIBRE_KM) c+=OPT_PENAL_DIAMETRO_KM*(diam-OPT_DIAMETRO_LIBRE_KM);
    cache.set(key,c); return c;
  }

  function clonar(st){ return st.map(function(a){return a.slice();}); }
  function total(st){ let t=0; st.forEach(function(ids,si){ t+=costoSlot(si,ids); }); return t; }
  function mejorar(st){
    let mejora=true, it=0;
    while(mejora && it<60 && Date.now()-t0<OPT_PRESUPUESTO_MS){
      mejora=false; it++;
      // relocate
      for(let a=0;a<st.length;a++){
        for(const id of st[a].slice()){
          const ca=costoSlot(a,st[a]); const sinU=st[a].filter(function(x){return x!==id;});
          const caNew=costoSlot(a,sinU);
          let mejorB=-1,mejorD=-1e-6;
          for(let b=0;b<st.length;b++){ if(b===a) continue;
            const d=caNew+costoSlot(b,st[b].concat([id]))-ca-costoSlot(b,st[b]);
            if(d<mejorD){mejorD=d;mejorB=b;} }
          if(mejorB>=0){ st[a]=sinU; st[mejorB].push(id); mejora=true; }
        }
      }
      // swap
      for(let a=0;a<st.length;a++) for(let b=a+1;b<st.length;b++){
        for(const x of st[a].slice()) for(const y of st[b].slice()){
          if(st[a].indexOf(x)<0||st[b].indexOf(y)<0) continue;
          const na=st[a].filter(function(i){return i!==x;}).concat([y]);
          const nb=st[b].filter(function(i){return i!==y;}).concat([x]);
          const d=costoSlot(a,na)+costoSlot(b,nb)-costoSlot(a,st[a])-costoSlot(b,st[b]);
          if(d<-1e-6){ st[a]=na; st[b]=nb; mejora=true; }
        }
      }
      // fusionar dos rutas completas en una sola (útil cuando quedan viajes chicos del mismo sector)
      for(let a=0;a<st.length;a++) for(let b=0;b<st.length;b++){
        if(a===b||!st[a].length||!st[b].length) continue;
        const un=st[b].concat(st[a]);
        if(costoSlot(b,un)<costoSlot(a,st[a])+costoSlot(b,st[b])-1e-6){ st[b]=un; st[a]=[]; mejora=true; }
      }
      // cerrar una ruta repartiendo sus bloques en las demás
      for(let a=0;a<st.length;a++){
        if(!st[a].length) continue;
        const copia=clonar(st); const mover=copia[a].slice(); copia[a]=[]; let ok=true;
        mover.sort(function(p,q){return unidades[q].vol-unidades[p].vol;});
        for(const id of mover){
          let bb=-1,bd=Infinity;
          for(let b=0;b<copia.length;b++){ if(b===a) continue; const d=costoSlot(b,copia[b].concat([id]))-costoSlot(b,copia[b]); if(d<bd){bd=d;bb=b;} }
          if(bb<0){ok=false;break;} copia[bb].push(id);
        }
        if(ok && total(copia)<total(st)-1e-6){ for(let i=0;i<st.length;i++) st[i]=copia[i]; mejora=true; }
      }
    }
    return st;
  }

  // --- Solución inicial A: la que ya armó el motor ---
  const stA=slots.map(function(){return [];});
  const ocup=new Set();
  rutasRM.forEach(function(r){
    let si=slots.findIndex(function(s,i){return s.camion.patente===r.patente && s.vuelta===(r.vueltaNumero||1) && !ocup.has(i);});
    if(si<0) si=slots.findIndex(function(s,i){return !ocup.has(i);});
    if(si<0) si=0;
    ocup.add(si);
    const ids=new Set(); r.stops.forEach(function(s){ { const pu=porClave.get(claveDireccionStop(s)); if(pu.id>=0) ids.add(pu.id); } });
    ids.forEach(function(id){ stA[si].push(id); });
  });
  // evitar duplicados si una ruta cayó en un slot ya usado
  const vistos=new Set(); stA.forEach(function(ids,si){ stA[si]=ids.filter(function(id){ if(vistos.has(id)) return false; vistos.add(id); return true; }); });
  const costoInicial=total(stA);

  // --- Solución inicial B: inserción desde cero (más lejanos primero) ---
  const stB=slots.map(function(){return [];});
  unidades.slice().sort(function(p,q){
    const cp=coordStop(p.stops[0]),cq=coordStop(q.stops[0]);
    return calcularDistanciaKm({lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng},{lat:cq.lat,lng:cq.lon})-calcularDistanciaKm({lat:BASE_LAMPA.lat,lng:BASE_LAMPA.lng},{lat:cp.lat,lng:cp.lon});
  }).forEach(function(u){
    let bb=0,bd=Infinity;
    for(let b=0;b<stB.length;b++){ const d=costoSlot(b,stB[b].concat([u.id]))-costoSlot(b,stB[b]); if(d<bd){bd=d;bb=b;} }
    stB[bb].push(u.id);
  });

  // --- Soluciones iniciales C(k): agrupar por cercanía en k grupos (k-means sobre ubicación) ---
  const semillas=[stA,stB];
  const volTotal=unidades.reduce(function(a,u){return a+u.vol;},0);
  const slotsOrd=slots.map(function(sl,i){return i;}).sort(function(a,b){return slots[b].cap-slots[a].cap;});
  const kMin=Math.max(1,Math.ceil(volTotal/Math.max.apply(null,slots.map(function(x){return x.cap;}))));
  for(let k=kMin;k<=Math.min(slots.length,kMin+3);k++){
    const g=kmeansSplit(unidades.map(function(u){return {id:u.id,_comunaInfo:{lat:u.lat,lon:u.lon},lat:u.lat,lon:u.lon};}),k);
    const st=slots.map(function(){return [];});
    g.sort(function(a,b){ const va=a.reduce(function(x,u){return x+unidades[u.id].vol;},0), vb=b.reduce(function(x,u){return x+unidades[u.id].vol;},0); return vb-va; });
    g.forEach(function(grupo,gi){ grupo.forEach(function(u){ st[slotsOrd[gi]].push(u.id); }); });
    semillas.push(st);
  }
  // --- Soluciones iniciales D: barrido angular alrededor de la base (sectores contiguos) ---
  const angulo=unidades.map(function(u){ return Math.atan2(u.lat-BASE_LAMPA.lat, u.lon-BASE_LAMPA.lng); });
  const ordAng=unidades.map(function(u,i){return i;}).sort(function(a,b){return angulo[a]-angulo[b];});
  const capRef=Math.max.apply(null,slots.map(function(x){return x.meta;}));
  const tSweep=Date.now();
  for(let k=kMin;k<=slots.length && Date.now()-tSweep<1200;k++){
    const objetivo=Math.min(capRef*1.1, Math.max(volTotal/k*1.05, 1));
    for(let off=0;off<nU;off++){
      const grupos=[[]]; let acum=0;
      for(let q=0;q<nU;q++){
        const id=ordAng[(off+q)%nU]; const u=unidades[id];
        if(acum>0 && acum+u.vol>objetivo+1e-9){ grupos.push([]); acum=0; }
        grupos[grupos.length-1].push(id); acum+=u.vol;
      }
      if(grupos.length>slots.length) continue;
      grupos.sort(function(a,b){ return b.reduce(function(x,i){return x+unidades[i].vol;},0)-a.reduce(function(x,i){return x+unidades[i].vol;},0); });
      const st=slots.map(function(){return [];});
      grupos.forEach(function(g,gi){ st[slotsOrd[gi]]=g.slice(); });
      semillas.push(st);
    }
  }
  let mejorSt=null,mejorC=Infinity;
  semillas.forEach(function(st){ const s2=mejorar(clonar(st)); const c=total(s2); if(c<mejorC){mejorC=c;mejorSt=s2;} });

  // --- Búsqueda iterada: destruir parcialmente y reconstruir, aceptando solo mejoras ---
  const rnd=_rng(20260101); let iters=0;
  while(Date.now()-t0<OPT_PRESUPUESTO_MS && iters<400){
    iters++;
    const cand=clonar(mejorSt);
    const ocupados=cand.map(function(ids,i){return ids.length?i:-1;}).filter(function(i){return i>=0;});
    const nDestruir=1+Math.floor(rnd()*2);
    const quitar=[];
    for(let k=0;k<nDestruir && ocupados.length;k++){
      const sel=ocupados.splice(Math.floor(rnd()*ocupados.length),1)[0];
      // saca una parte (o todo) de ese camión
      const ids=cand[sel]; const frac=rnd()<0.5?1:0.5;
      const cuantos=Math.max(1,Math.round(ids.length*frac));
      for(let q=0;q<cuantos;q++){ const j=Math.floor(rnd()*ids.length); quitar.push(ids.splice(j,1)[0]); }
    }
    quitar.sort(function(){return rnd()-0.5;});
    quitar.forEach(function(id){
      let bb=0,bd=Infinity;
      for(let b=0;b<cand.length;b++){ const d=costoSlot(b,cand[b].concat([id]))-costoSlot(b,cand[b]); if(d<bd){bd=d;bb=b;} }
      cand[bb].push(id);
    });
    mejorar(cand);
    const c=total(cand);
    if(c<mejorC-1e-6){ mejorC=c; mejorSt=cand; }
  }

  if(process.env.OPT_DEBUG){ mejorSt.forEach(function(ids,si){ if(ids.length) console.log('SLOT',si,slots[si].camion.patente,'v'+slots[si].vuelta,'cost',costoSlot(si,ids).toFixed(1),ids.map(function(i){return unidades[i].stops[0].comuna.slice(0,6);}).join(','));}); console.log('slots',slots.length,'mejorC',mejorC,'inicial',costoInicial); }
  // --- Validación: nada sobre el 100% y todo pedido sigue asignado una sola vez ---
  for(let si=0;si<mejorSt.length;si++){
    const vol=mejorSt[si].reduce(function(a,id){return a+unidades[id].vol;},0);
    if(vol>slots[si].cap+1e-9) return null;
  }
  const nAsignados=mejorSt.reduce(function(a,ids){return a+ids.length;},0);
  if(nAsignados!==unidades.length) return null;
  if(mejorC>costoInicial-1e-6 && costoInicial<1000) { /* nada mejor que lo original */ return {sinCambios:true,costoAntes:costoInicial,costoDespues:costoInicial,iteraciones:iters}; }

  // --- Reconstrucción de las rutas ---
  const nuevas=[];
  mejorSt.forEach(function(ids,si){
    if(!ids.length) return;
    const stops=[]; ids.forEach(function(id){ unidades[id].stops.forEach(function(s){stops.push(s);}); });
    const sl=slots[si];
    const zonaReal=calcularEtiquetaPorContenido(stops)||'Ruta';
    const cont={}; stops.forEach(function(s){const z=zonaOperativaDeStop(s)||'?'; cont[z]=(cont[z]||0)+1;});
    const padre=Object.keys(cont).sort(function(a,b){return cont[b]-cont[a];})[0];
    const cor=corredorOperativoDeStop(stops[0])||'';
    const r={zona:zonaReal,zonaCodigo:padre,corredorCodigo:cor,corredorLabel:zonaReal,stops:stops,volumen:0,volumenRetiro:0,
      patente:sl.camion.patente,meta:sl.camion.meta,mts3:sl.camion.mts3,transportista:sl.camion.transportista,estado:'OK - Dentro de meta',
      vueltaNumero:sl.vuelta,tipoVuelta:sl.vuelta===2?'SEGUNDA VUELTA':'PRIMERA VUELTA',
      stopsOrdenados:[],distTotalKm:0,_routeEngine:'Optimizador geográfico global (reubicación + intercambio + orden con retiros al final)'};
    recalcularRuta(r);
    nuevas.push(r);
  });
  // Bloques demasiado grandes para cualquier camión: se cargan en la ruta más cercana de su sector
  grandes.forEach(function(g){
    if(!nuevas.length) return;
    const c=coordStop(g.stops[0])||{lat:BASE_LAMPA.lat,lon:BASE_LAMPA.lng}; const cor=corredorOperativoDeStop(g.stops[0]);
    let mejor=null,md=Infinity;
    nuevas.forEach(function(r){
      let la=0,lo=0,n=0; r.stops.forEach(function(s){ const cc=coordStop(s); if(cc){la+=cc.lat;lo+=cc.lon;n++;} });
      const ce=n?{lat:la/n,lon:lo/n}:{lat:BASE_LAMPA.lat,lon:BASE_LAMPA.lng};
      let d=calcularDistanciaKm({lat:c.lat,lng:c.lon},{lat:ce.lat,lng:ce.lon});
      if(cor && r.stops.some(function(x){return corredorOperativoDeStop(x)===cor;})) d-=15;
      if(d<md){md=d;mejor=r;}
    });
    g.stops.forEach(function(s){ mejor.stops.push(s); });
    recalcularRuta(mejor);
  });
  // Ordena por camión/vuelta; un camión con una sola vuelta activa la lleva como 1ª
  const porPat={}; nuevas.forEach(function(r){(porPat[r.patente]||(porPat[r.patente]=[])).push(r);});
  Object.keys(porPat).forEach(function(p){ const rs=porPat[p].sort(function(a,b){return a.vueltaNumero-b.vueltaNumero;}); rs.forEach(function(r,i){ r.vueltaNumero=i+1; r.tipoVuelta=i===1?'SEGUNDA VUELTA':'PRIMERA VUELTA'; }); });

  const cambios=[];
  nuevas.forEach(function(r){
    const et=r.patente+' V'+r.vueltaNumero;
    r.stops.forEach(function(s){ const o=origenDe[norm(s.pedido)]; if(o!==et) cambios.push({pedido:s.pedido,desde:o,hacia:et}); });
  });
  return {rutasNuevas:nuevas,reemplaza:rutasRM,cambios:cambios,costoAntes:costoInicial,costoDespues:mejorC,iteraciones:iters,camionesUsados:Object.keys(porPat).length,rutasUsadas:nuevas.length};
}


/* ======================================================================
   VALIDACIÓN DIRECCIÓN ↔ COMUNA
   SAP a veces trae la comuna equivocada para una dirección (p.ej. Alberto Lo
   Seco 2270 como "Santiago" cuando es Quinta Normal). Se busca la dirección
   en Mapbox SIN la comuna y se mira en qué comuna(s) aparece:
     - si alguna coincide con la de SAP  → 'ok'
     - si ninguna coincide y el mejor resultado está en otra comuna → 'distinta'
       (con la comuna sugerida)
     - si Mapbox no sabe / no hay datos → 'sin_datos' (no se alerta)
   Es solo un aviso para revisar: nunca cambia la comuna por sí solo.
   ====================================================================== */
function _claveComunaComparable(c){
  let k=comunaKeyResuelta(c);
  k=norm(k).replace(/\s+/g,' ');
  if(k==='SANTIAGO CENTRO') k='SANTIAGO';
  return k;
}
function mismaComuna(a,b){ return _claveComunaComparable(a)===_claveComunaComparable(b); }

const _cacheValidacionComuna=new Map();
async function validarComunaDireccion(direccion, comunaSAP){
  const dirBase=direccionBaseParaGeo(direccion);
  const key=norm(dirBase)+'|'+_claveComunaComparable(comunaSAP);
  if(_cacheValidacionComuna.has(key)) return _cacheValidacionComuna.get(key);
  const cands=await mapbox.candidatosComunaMapbox(dirBase);
  let res={estado:'sin_datos',sugerida:''};
  if(cands && cands.length){
    const conComuna=cands.filter(function(c){return c.comunas.length;});
    if(conComuna.some(function(c){return c.comunas.some(function(n){return mismaComuna(n,comunaSAP);});})){
      res={estado:'ok',sugerida:''};
    } else if(conComuna.length && conComuna[0].relevancia>=0.8){
      res={estado:'distinta',sugerida:conComuna[0].comunas[0],detalle:conComuna[0].nombre};
    }
  }
  if(res.estado!=='sin_datos' || cands) _cacheValidacionComuna.set(key,res);
  return res;
}

/* items: [{direccion, comuna}] → [{direccion, comuna, estado, sugerida}] (en el mismo orden). */
async function validarComunasLista(items, maxConsultas){
  const tope=maxConsultas||150;
  const unicos=new Map();
  items.forEach(function(it){
    if(!it.direccion||!it.comuna) return;
    const k=norm(direccionBaseParaGeo(it.direccion))+'|'+_claveComunaComparable(it.comuna);
    if(!unicos.has(k)) unicos.set(k,it);
  });
  const claves=Array.from(unicos.keys()).slice(0,tope);
  const resultados=new Map();
  let idx=0;
  async function worker(){
    while(idx<claves.length){
      const k=claves[idx++]; const it=unicos.get(k);
      resultados.set(k,await validarComunaDireccion(it.direccion,it.comuna));
    }
  }
  await Promise.all([worker(),worker(),worker(),worker()]);
  return items.map(function(it){
    const k=norm(direccionBaseParaGeo(it.direccion||''))+'|'+_claveComunaComparable(it.comuna||'');
    const r=resultados.get(k)||{estado:'sin_datos',sugerida:''};
    return {direccion:it.direccion,comuna:it.comuna,estado:r.estado,sugerida:r.sugerida||''};
  });
}

async function planificar(pedidosRaw, fleetDisponible, onGeoProgress){
  (pedidosRaw||[]).forEach(normalizarVolumenLinea);
  const stopsAll=consolidar(pedidosRaw);

  /* Detección de datos inconsistentes: la MISMA dirección apareciendo con
     comunas distintas entre pedidos (típicamente un error de tipeo en la
     planilla de origen — la comuna real es una sola). No se corrige solo:
     se avisa, porque adivinar cuál de las dos comunas es la correcta podría
     mandar el pedido al sector equivocado. */
  const direccionesInconsistentes=(function(){
    const porDireccion={};
    stopsAll.forEach(function(s){
      if(!s.direccion) return;
      const key=norm(s.direccion);
      if(!porDireccion[key]) porDireccion[key]={};
      const ck=norm(s.comuna)||'(SIN COMUNA)';
      (porDireccion[key][ck]||(porDireccion[key][ck]=[])).push(s);
    });
    const resultado=[];
    Object.keys(porDireccion).forEach(function(key){
      const comunas=Object.keys(porDireccion[key]);
      if(comunas.length>1){
        resultado.push({
          direccion: porDireccion[key][comunas[0]][0].direccion,
          variantes: comunas.map(function(c){ return {comuna:c, pedidos: porDireccion[key][c].map(function(s){return s.pedido;})}; })
        });
      }
    });
    return resultado;
  })();
  const forceKeys=new Set(); // en el servidor no hay botón de "forzar re-geocodificación"; siempre usa caché normal
  const geocodables=stopsAll.filter(function(s){return !s.esOtraRegion&&s._comunaInfo&&s.direccion;});
  if(geocodables.length) await geocodificarStops(geocodables,forceKeys,onGeoProgress);
  /* Validación dirección ↔ comuna (aviso, no cambia nada). */
  let alertasComuna=[];
  try{
    const aValidar=stopsAll.filter(function(s){return s.direccion&&s.comuna&&!s.esOtraRegion&&s._comunaInfo;});
    const vr=await validarComunasLista(aValidar.map(function(s){return {direccion:s.direccion,comuna:s.comuna};}));
    aValidar.forEach(function(s,i){
      s._comunaValidacion=vr[i].estado;
      if(vr[i].estado==='distinta'){ s._comunaSugerida=vr[i].sugerida; alertasComuna.push({pedido:s.pedido,direccion:s.direccion,comunaSAP:s.comuna,comunaSugerida:vr[i].sugerida}); }
    });
  }catch(e){ console.error('validación de comunas falló (se ignora):',e&&e.message); }
  stopsAll.forEach(function(s){if(!Number.isFinite(Number(s.lat))){const c=coordFallbackComuna(s);if(c){s.lat=c.lat;s.lon=c.lon;s._geoExact=false;s._geoSource='comuna';}}});

  // Regla de operación: >13 m³ siempre queda fuera de las rutas locales.
  const excluidosMas13=stopsAll.filter(function(s){return Number(s.volumen)>13+1e-9;});
  /* Regla dura: >13 m³ nunca entra al ruteo urbano.
     La version anterior usaba <=15 aqui, contradiciendo la regla de >13 m³
     y permitiendo que pedidos de 13-15 m³ terminaran en una ruta normal. */
  excluidosMas13.forEach(function(s){ s._alertaRevision='Supera 13 m³ ('+(Number(s.volumen)||0).toFixed(1)+' m³): se cargó en la ruta de su sector, revisar transporte y dirección'; });
  const stopsOperables=stopsAll.slice(); /* los >13 m³ se rutean igual (con advertencia), nunca quedan fuera */
  const paraOtraRegion=stopsOperables.filter(function(s){return s.esOtraRegion;});
  const stopsRM=stopsOperables.filter(function(s){return !s.esOtraRegion;});
  const sinClasificar=stopsRM.filter(function(s){return !s._comunaInfo;});
  const stopsRMConocidos=stopsRM.filter(function(s){return s._comunaInfo;});
  const maxCapSel=fleetDisponible.length?Math.max.apply(null,fleetDisponible.map(function(f){return f.mts3;})):0;
  const imposibles=[];
  const stopsRuteables=stopsRMConocidos.slice();

  /* Agrupamos primero por corredor interno y solo después asignamos flota.
     Así Pudahuel/Poniente no puede terminar con La Reina/Suroriente, y Paine
     queda en el corredor Periférico Sur aunque el volumen sea pequeño. */
  const porCorredor={};
  stopsRuteables.forEach(function(s){
    const corredor=corredorOperativoDeStop(s);
    if(!corredor){sinClasificar.push(s);return;}
    (porCorredor[corredor]||(porCorredor[corredor]=[])).push(s);
  });
  const volPorCorredor={};
  Object.keys(porCorredor).forEach(function(z){volPorCorredor[z]=porCorredor[z].reduce(function(a,s){return a+volCarga(s);},0);});
  const fusionesRealizadas=[];

  /* Uso de flota mínima: aunque alcancen camiones para darle uno a cada
     corredor, no tiene sentido sacar un camión completo (con su chofer y
     kilómetros) para un corredor con muy poco volumen si ese volumen cabe
     perfectamente en una vuelta de un camión ya asignado a un corredor
     VECINO del mismo macro-sector. Antes el sistema siempre repartía un
     camión por corredor sin mirar el volumen, dejando camiones con 20-30%
     de carga recorriendo el sector completo solo porque "les tocaba" un
     corredor propio. Igual que la fusión por escasez de flota (más abajo),
     esto NUNCA junta corredores de macro-sectores distintos — solo evita
     gastar flota de más dentro del mismo sector operativo. */
  if(fleetDisponible.length && Object.keys(porCorredor).length>1){
    const capMax2Vueltas=Math.max.apply(null, fleetDisponible.map(function(f){return capacidadEfectivaDosVueltas(f);}));
    const metaProm=(fleetDisponible.reduce(function(a,f){return a+(Number(f.meta)||0);},0)/fleetDisponible.length)||0;
    const umbralChico=metaProm*0.5;
    let cambiado=true, guardaVol=0;
    while(cambiado && guardaVol<50){
      cambiado=false; guardaVol++;
      const claves=Object.keys(porCorredor).sort(function(a,b){return volPorCorredor[a]-volPorCorredor[b];});
      if(claves.length<=1) break;
      for(let i=0;i<claves.length;i++){
        const chico=claves[i];
        if(volPorCorredor[chico]>=umbralChico) break; // ordenados ascendente: ya no quedan "chicos"
        let destino=null, mejorVolTras=Infinity;
        claves.forEach(function(k){
          if(k===chico) return;
          if(CORREDOR_PADRE[k]!==CORREDOR_PADRE[chico]) return; // nunca cruza macro-sector
          const volTras=volPorCorredor[k]+volPorCorredor[chico];
          if(volTras<=capMax2Vueltas+1e-9 && volTras<mejorVolTras){ mejorVolTras=volTras; destino=k; }
        });
        /* Corredor "huérfano": muy poco volumen y sin ningún corredor del
           mismo macro-sector con el que fusionarse (p.ej. un único pedido
           chico en Periférico Sur, sin nada más de esa zona ese día). Antes
           esto terminaba en un camión ENTERO dedicado a una sola entrega
           chica y aislada — kilómetros y chofer gastados en casi nada,
           mientras otro camión quedaba sobrecargado con el resto. Un
           despachador real simplemente agrega esa entrega como parada extra
           a la ruta más cercana que tenga espacio, aunque sea de otro
           macro-sector — es una excepción acotada solo a volúmenes realmente
           chicos (no reabre la puerta a mezclar corredores grandes, que es
           justo lo que se pidió evitar). */
        if(!destino && volPorCorredor[chico] <= umbralChico*0.3 + 1e-9 && claves.length>1){
          const cChico=centroideStops(porCorredor[chico]);
          let mejorDistGlobal=Infinity;
          claves.forEach(function(k){
            if(k===chico) return;
            const volTras=volPorCorredor[k]+volPorCorredor[chico];
            if(volTras>capMax2Vueltas+1e-9) return;
            const cK=centroideStops(porCorredor[k]);
            const d=haversine(cChico.lon,cChico.lat,cK.lon,cK.lat);
            if(d<mejorDistGlobal){ mejorDistGlobal=d; destino=k; }
          });
        }
        if(destino){
          porCorredor[destino]=porCorredor[destino].concat(porCorredor[chico]);
          volPorCorredor[destino]=volPorCorredor[destino]+volPorCorredor[chico];
          fusionesRealizadas.push({de:CORREDOR_LABEL[chico]||chico, en:CORREDOR_LABEL[destino]||destino});
          delete porCorredor[chico];
          delete volPorCorredor[chico];
          cambiado=true;
          break;
        }
      }
    }
  }

  /* Si hay MENOS patentes seleccionadas que corredores con pedidos, el reparto
     por corredor de más abajo dejaría corredores enteros sin camión (aunque
     las patentes elegidas tengan capacidad de sobra con una 2ª vuelta), porque
     una patente no se reparte entre dos corredores. Eso es justo lo que se
     reportó como "poco eficiente / separa todo": con 2 camiones seleccionados,
     el sistema arma 2 rutas chicas y deja 3 sectores en "SIN CAMIÓN DISPONIBLE".
     Para evitarlo, cuando faltan camiones para cubrir todos los corredores se
     fusionan corredores hasta que la cantidad de grupos activos quepa dentro de
     la flota seleccionada. El orden de fusión importa mucho para que el
     resultado sea geográficamente coherente:
       1) Primero se fusionan corredores que YA comparten el mismo macro-sector
          (p.ej. A_NORTE con A_ORIENTE, o B_CENTRO con B_PONIENTE) — eso siempre
          tiene sentido porque nacen del mismo sector operativo.
       2) Solo si con eso no alcanza, se fusiona el PAR de grupos más cercano
          entre sí en todo el mapa (no "el más chico con su vecino más cercano",
          que podía separar dos corredores del mismo macro-sector — p.ej. dejar
          Santiago (B_CENTRO) en una ruta y Quinta Normal/Pudahuel/Maipú
          (B_PONIENTE) en otra — solo porque otro corredor lejano quedaba
          numéricamente "más cerca" del más chico en ese momento). */
  if(fleetDisponible.length){
    let corredoresActivos=Object.keys(porCorredor);
    let guardaInfinita=0;
    while(corredoresActivos.length>fleetDisponible.length && corredoresActivos.length>1 && guardaInfinita<50){
      guardaInfinita++;
      let par=null;
      // Fase 1: mismo macro-sector (A/B/C/D)
      for(let i=0;i<corredoresActivos.length && !par;i++){
        for(let j=i+1;j<corredoresActivos.length;j++){
          const a=corredoresActivos[i], b=corredoresActivos[j];
          if(CORREDOR_PADRE[a] && CORREDOR_PADRE[a]===CORREDOR_PADRE[b]){ par=[a,b]; break; }
        }
      }
      // Fase 2: el par de grupos geográficamente más cercano entre sí (centroide real)
      if(!par){
        let mejorDist=Infinity;
        for(let i=0;i<corredoresActivos.length;i++){
          for(let j=i+1;j<corredoresActivos.length;j++){
            const ca=centroideStops(porCorredor[corredoresActivos[i]]);
            const cb=centroideStops(porCorredor[corredoresActivos[j]]);
            const d=haversine(ca.lon,ca.lat,cb.lon,cb.lat);
            if(d<mejorDist){ mejorDist=d; par=[corredoresActivos[i],corredoresActivos[j]]; }
          }
        }
      }
      if(!par) break;
      // El corredor de menor volumen se absorbe dentro del de mayor volumen,
      // así la ruta conserva la etiqueta/zona del grupo dominante.
      const chico = volPorCorredor[par[0]]<=volPorCorredor[par[1]] ? par[0] : par[1];
      const grande = chico===par[0] ? par[1] : par[0];
      porCorredor[grande]=porCorredor[grande].concat(porCorredor[chico]);
      volPorCorredor[grande]=(volPorCorredor[grande]||0)+(volPorCorredor[chico]||0);
      fusionesRealizadas.push({de:CORREDOR_LABEL[chico]||chico, en:CORREDOR_LABEL[grande]||grande});
      delete porCorredor[chico];
      delete volPorCorredor[chico];
      corredoresActivos=Object.keys(porCorredor);
    }
    // Fusionar corredores por cercanía puede dejar un grupo enorme y otro casi
    // vacío (p.ej. todo el norte/centro/poniente junto vs. un grupito de 2
    // comunas del sur) aunque ambos "quepan" físicamente: dos camiones iguales
    // terminan con cargas de trabajo totalmente distintas. Por eso, si hubo
    // fusiones, se pareja el volumen entre los grupos finales moviendo — de a
    // una — la parada del grupo más cargado que esté geográficamente más cerca
    // del centro del grupo más liviano, hasta que la diferencia sea razonable
    // (±8%) o ya no quede nada sensato que mover. Esto no vuelve a mezclar
    // corredores al azar: solo ajusta el límite entre los grupos ya formados.
    if(fusionesRealizadas.length && corredoresActivos.length>1){
      const claves=Object.keys(porCorredor);
      // Parejar por volumen absoluto asume patentes del mismo tamaño. Si la
      // flota seleccionada mezcla camiones grandes y chicos (p.ej. 40m³ y
      // 15m³), hay que parejar por PROPORCIÓN de capacidad o el camión chico
      // termina recibiendo un grupo que nunca le va a caber ni en 2 vueltas.
      // Se estima qué capacidad le tocaría a cada grupo emparejando, de mayor
      // a mayor, el volumen actual del corredor con la capacidad (2 vueltas)
      // de la patente disponible más grande — es solo una aproximación (la
      // asignación real la hace asignarCamionesPorSector después), pero evita
      // el caso más grave: un grupo enorme cayendo sobre el camión más chico.
      const capacidadesDesc=fleetDisponible.map(function(f){return capacidadEfectivaDosVueltas(f);}).sort(function(a,b){return b-a;});
      const clavesPorVolumen=claves.slice().sort(function(a,b){return volPorCorredor[b]-volPorCorredor[a];});
      const pesoPorClave={};
      clavesPorVolumen.forEach(function(k,i){ pesoPorClave[k]=capacidadesDesc[i]||capacidadesDesc[capacidadesDesc.length-1]||1; });
      const partesBalanceadas=rebalancearGruposPorComuna(claves.map(function(k){return porCorredor[k];}), 200, claves.map(function(k){return pesoPorClave[k];}));
      claves.forEach(function(k,i){
        porCorredor[k]=partesBalanceadas[i];
        volPorCorredor[k]=partesBalanceadas[i].reduce(function(a,s){return a+volCarga(s);},0);
      });
    }
  }

  const asignacion=asignarCamionesPorSector(volPorCorredor,fleetDisponible);
  const rutas=[];
  const sinCamion=[];
  // (los pedidos >13 m³ se cargan más abajo como rutas "⚠ REVISAR", una por pedido)

  Object.keys(porCorredor).sort(function(a,b){return volPorCorredor[b]-volPorCorredor[a];}).forEach(function(corredor){
    const flotaSector=asignacion[corredor]||[];
    const padre=CORREDOR_PADRE[corredor];
    const label=CORREDOR_LABEL[corredor];
    /* La etiqueta de zona mostrada en pantalla se calcula a partir de las
       comunas REALES que quedaron en este grupo (no del nombre fijo del
       corredor original). Cuando la flota es muy escasa, la fusión de
       corredores puede juntar comunas de macro-sectores distintos (p.ej.
       Norte con Centro/Poniente); si ahí se siguiera mostrando el nombre fijo
       del corredor que "sobrevivió" a la fusión, la etiqueta terminaría
       contradiciendo la lista de comunas de la propia ruta (el error que
       reportó el usuario: rutas tituladas "Norte + Nororiente" que en
       realidad contenían Santiago/Estación Central/Maipú/Pudahuel). */
    const zonaReal=calcularEtiquetaPorContenido(porCorredor[corredor])||MACRO_LABEL[padre];
    if(!flotaSector.length){
      const stopsCont=nearestNeighborDesdeLampa(porCorredor[corredor]);
      rutas.push({zona:zonaReal,zonaCodigo:padre,corredorCodigo:corredor,corredorLabel:zonaReal,stops:porCorredor[corredor],volumen:volPorCorredor[corredor],volumenRetiro:0,patente:null,meta:null,mts3:null,transportista:null,vueltaNumero:1,tipoVuelta:'CONTINGENCIA',estado:'CONTINGENCIA — SIN CAMIÓN DISPONIBLE',stopsOrdenados:stopsCont,distTotalKm:distanciaRutaNN(stopsCont),_routeEngine:'Contingencia por sector'});
      return;
    }
    const part=particionarSectorNN(porCorredor[corredor],flotaSector);
    part.grupos.forEach(function(g){
      const stopsOrdenados=nearestNeighborDesdeLampa(g.stops);
      const volumen=g.stops.reduce(function(a,s){return a+volCarga(s);},0);
      const volumenRetiro=g.stops.filter(function(s){return s.esRetiro;}).reduce(function(a,s){return a+s.volumen;},0);
      const f=g.camion;
      let estado='OK - Dentro de meta';
      if(volumen>f.mts3+1e-9) estado='SOBRECARGA — REVISAR CAPACIDAD';
      else if(volumen>f.meta+1e-9) estado='SOBRE META 70% — ASIGNADO';
      rutas.push({zona:zonaReal,zonaCodigo:padre,corredorCodigo:corredor,corredorLabel:zonaReal,stops:g.stops,volumen,volumenRetiro,
        patente:f.patente,meta:f.meta,mts3:f.mts3,transportista:f.transportista,estado,
        vueltaNumero:g.vueltaNumero||1, tipoVuelta:g.tipoVuelta||((g.vueltaNumero||1)===2?'SEGUNDA VUELTA':'PRIMERA VUELTA'),
        stopsOrdenados,distTotalKm:distanciaRutaNN(stopsOrdenados),_routeEngine:'Nearest Neighbor + 2-opt por corredor desde Lampa'});
    });
    if(part.sinCamion.length){ const cont=nearestNeighborDesdeLampa(part.sinCamion); rutas.push({zona:zonaReal,zonaCodigo:padre,corredorCodigo:corredor,corredorLabel:zonaReal,stops:part.sinCamion,volumen:part.sinCamion.reduce(function(a,s){return a+volCarga(s);},0),volumenRetiro:0,patente:null,meta:null,mts3:null,transportista:null,vueltaNumero:1,tipoVuelta:'CONTINGENCIA',estado:'CONTINGENCIA — REMANENTE ASIGNADO',stopsOrdenados:cont,distTotalKm:distanciaRutaNN(cont),_routeEngine:'Contingencia por sector'}); }
  });

  /* Rebalanceo global por corredor: analiza simultáneamente los excedentes de
     las rutas ya creadas y consolida remanentes donde exista capacidad física. */
  Object.keys(porCorredor).forEach(function(corredor){
    const grupoRutas=rutas.filter(function(r){return r.corredorCodigo===corredor && r.patente;});
    rebalancearExcedentesCorredor(grupoRutas);
  });
  rutas.forEach(function(r){ if(r.patente) recalcularRuta(r); });

  /* Optimización geográfica global (ver optimizarGlobalRutas). Si falla o no
     encuentra nada mejor, las rutas quedan exactamente como estaban. */
  let optimizacionGlobal=null;
  try{
    const og=optimizarGlobalRutas(rutas, fleetDisponible);
    if(og && og.rutasNuevas){
      const quitar=new Set(og.reemplaza);
      for(let i=rutas.length-1;i>=0;i--){ if(quitar.has(rutas[i])) rutas.splice(i,1); }
      og.rutasNuevas.forEach(function(r){ rutas.push(r); });
      optimizacionGlobal={aplicada:true,cambios:og.cambios,costoAntes:og.costoAntes,costoDespues:og.costoDespues,iteraciones:og.iteraciones,camionesUsados:og.camionesUsados,rutasUsadas:og.rutasUsadas};
    } else if(og){ optimizacionGlobal={aplicada:false,cambios:[],costoAntes:og.costoAntes,costoDespues:og.costoDespues,iteraciones:og.iteraciones}; }
  }catch(e){ console.error('optimizarGlobalRutas falló, se conservan las rutas originales:',e); }

  /* Ningún pedido queda sin ruta: si un sector se quedó sin camión o el
     volumen no cabe, las paradas se cargan IGUAL en la ruta con patente de ese
     sector (la más parecida), aunque pase la meta o la capacidad: la ruta queda
     marcada como sobrecargada para que quien despacha decida. */
  (function absorberRutasSinCamion(){
    const conPat=rutas.filter(function(r){return r.patente && r.stops && r.stops.length;});
    if(!conPat.length) return;
    function centro(r){ let la=0,lo=0,n=0; r.stops.forEach(function(s){ const c=coordStop(s); if(c){la+=c.lat;lo+=c.lon;n++;} }); return n?{lat:la/n,lon:lo/n}:{lat:BASE_LAMPA.lat,lon:BASE_LAMPA.lng}; }
    rutas.slice().forEach(function(r0){
      if(r0.patente || r0.requiereRevision || !r0.stops || !r0.stops.length) return;
      r0.stops.slice().forEach(function(s){
        const c=coordStop(s)||{lat:BASE_LAMPA.lat,lon:BASE_LAMPA.lng}; const cor=corredorOperativoDeStop(s);
        let mejor=null,md=Infinity;
        conPat.forEach(function(r){
          const ce=centro(r); let d=calcularDistanciaKm({lat:c.lat,lng:c.lon},{lat:ce.lat,lng:ce.lon});
          if(cor && r.stops.some(function(x){return corredorOperativoDeStop(x)===cor;})) d-=15;
          if(d<md){md=d;mejor=r;}
        });
        mejor.stops.push(s);
      });
      const i=rutas.indexOf(r0); if(i>=0) rutas.splice(i,1);
    });
    conPat.forEach(function(r){ recalcularRuta(r); });
  })();

  /* Pedidos que las reglas dejan fuera del ruteo normal (más de 13 m³ o con
     comuna que el sistema no reconoce) IGUAL se cargan en el resultado, cada
     uno en una ruta "⚠ REVISAR", sin patente y con una advertencia en la propia
     parada. Así nunca faltan pedidos en la programación y quien despacha ve
     de inmediato cuáles hay que revisar a mano (transporte pesado o corregir
     la dirección/comuna). */
  function _rutaRevision(stopsRev, etiqueta, estado, motivo){
    stopsRev.forEach(function(s){ s._alertaRevision=motivo; });
    const ord=nearestNeighborDesdeLampa(stopsRev);
    ord.forEach(function(s){ s._alertaRevision=motivo; });
    return {zona:etiqueta,zonaCodigo:'REV',corredorCodigo:'REV',corredorLabel:etiqueta,stops:stopsRev,
      volumen:stopsRev.reduce(function(a,s){return a+volCarga(s);},0),
      volumenRetiro:stopsRev.filter(function(s){return s.esRetiro;}).reduce(function(a,s){return a+s.volumen;},0),
      patente:null,meta:null,mts3:null,transportista:null,vueltaNumero:1,tipoVuelta:'REVISIÓN MANUAL',
      estado:estado,requiereRevision:true,stopsOrdenados:ord,distTotalKm:distanciaRutaNN(ord),_routeEngine:'Revisión manual'};
  }
  const yaEnRutas=new Set(); rutas.forEach(function(r){(r.stops||[]).forEach(function(s){yaEnRutas.add(norm(s.pedido));});});
  const sinComunaRev=sinClasificar.filter(function(s){return !yaEnRutas.has(norm(s.pedido));});
  if(sinComunaRev.length){
    rutas.push(_rutaRevision(sinComunaRev,'⚠ REVISAR — comuna no reconocida','⚠ REVISAR — comuna no reconocida: corrige la comuna/dirección','Comuna no reconocida ("'+'" ): corregir comuna o dirección y volver a optimizar'));
    const r=rutas[rutas.length-1];
    r.stops.forEach(function(s){ const sg=sugerirComunaParecida(s.comuna); s._comunaSugerida=sg||s._comunaSugerida; s._alertaRevision='Comuna no reconocida ("'+(s.comuna||'sin comuna')+'")'+(sg?' — ¿será '+sg+'?':'')+': corrige comuna o dirección y vuelve a optimizar'; });
    r.stopsOrdenados.forEach(function(s){ const sg=sugerirComunaParecida(s.comuna); s._alertaRevision='Comuna no reconocida ("'+(s.comuna||'sin comuna')+'")'+(sg?' — ¿será '+sg+'?':'')+': corrige comuna o dirección y vuelve a optimizar'; });
  }

  // Fuera de RM queda aislado y no compite por la flota local.
  if(paraOtraRegion.length){
    const stopsOrdenados=nearestNeighborDesdeLampa(paraOtraRegion);
    rutas.push({zona:'🗺️ Fuera de la Región Metropolitana',zonaCodigo:'EXT',stops:paraOtraRegion,
      volumen:paraOtraRegion.reduce(function(a,s){return a+volCarga(s);},0),
      volumenRetiro:paraOtraRegion.filter(function(s){return s.esRetiro;}).reduce(function(a,s){return a+s.volumen;},0),
      patente:null,meta:null,mts3:null,transportista:null,
      estado:'FUERA DE LA REGIÓN METROPOLITANA — coordinar courier externo',
      stopsOrdenados,distTotalKm:distanciaRutaNN(stopsOrdenados),_routeEngine:'Aislada'});
  }

  /* Auditoría final: ningún pedido operable puede desaparecer silenciosamente.
     IMPORTANTE: se compara por número de pedido (norm(pedido)), no por referencia
     de objeto. nearestNeighborDesdeLampa() clona cada parada (Object.assign) al
     ordenar la ruta, así que la parada que termina dentro de r.stops NUNCA es el
     mismo objeto que el de stopsRMConocidos aunque sea el mismo pedido. Comparar
     por referencia (como antes) hacía que la auditoría no reconociera pedidos que
     SÍ estaban bien asignados, y los duplicaba en una segunda ruta "fantasma" de
     contingencia — pedidos repetidos dos veces en el resultado. */
  const asignados=new Set();
  rutas.forEach(function(r){(r.stops||[]).forEach(function(s){asignados.add(norm(s.pedido));});});
  const pendientesAuditoria=stopsRMConocidos.filter(function(s){return !asignados.has(norm(s.pedido));});
  if(pendientesAuditoria.length){
    const porCor={};
    pendientesAuditoria.forEach(function(s){const c=corredorOperativoDeStop(s)||'SIN_CORREDOR';(porCor[c]||(porCor[c]=[])).push(s);});
    Object.keys(porCor).forEach(function(c){
      const arr=porCor[c];
      const cont=nearestNeighborDesdeLampa(arr); rutas.push({zona:CORREDOR_LABEL[c]||c,zonaCodigo:CORREDOR_PADRE[c]||'?',corredorCodigo:c,stops:arr,volumen:arr.reduce(function(a,s){return a+volCarga(s);},0),volumenRetiro:0,patente:null,meta:null,mts3:null,transportista:null,vueltaNumero:1,tipoVuelta:'CONTINGENCIA',estado:'CONTINGENCIA — ASIGNACIÓN GARANTIZADA',stopsOrdenados:cont,distTotalKm:distanciaRutaNN(cont),_routeEngine:'Auditoría de cobertura total'});
    });
  }

  // El rebalanceo de excedentes puede dejar una vuelta con 0 paradas (movió todo
  // su contenido a otra ruta). Esa tarjeta vacía no aporta nada y solo confunde
  // en pantalla, así que no se incluye en el resultado final.
  const rutasFinales=rutas.filter(function(r){return (r.stops||[]).length>0;});

  // Si ese mismo rebalanceo dejó a un camión con UNA SOLA vuelta activa (la
  // otra quedó vacía y se descartó arriba), esa vuelta sobreviviente debe
  // quedar como "1ª vuelta": mostrarle al chofer "2ª VUELTA" cuando en
  // realidad es el único viaje que va a hacer ese día es confuso y puede
  // hacer pensar que falta una carga anterior.
  const porPatenteVueltas={};
  rutasFinales.forEach(function(r){
    if(!r.patente) return;
    (porPatenteVueltas[r.patente]||(porPatenteVueltas[r.patente]=[])).push(r);
  });
  Object.keys(porPatenteVueltas).forEach(function(pat){
    const rs=porPatenteVueltas[pat];
    // Renumeración defensiva: nunca dos rutas del mismo camión con el mismo número de vuelta
    rs.sort(function(a,b){return (a.vueltaNumero||1)-(b.vueltaNumero||1);});
    rs.forEach(function(r,i){ r.vueltaNumero=i+1; r.tipoVuelta=i===0?'PRIMERA VUELTA':(i===1?'SEGUNDA VUELTA':('VUELTA '+(i+1))); });
  });

  // Alerta de ruta dispersa: una ruta que mezcla 3 o más corredores recorre media ciudad
  rutasFinales.forEach(function(r){
    if(!r.patente || !r.stops) return;
    const cs=new Set(); r.stops.forEach(function(s){ const c=corredorOperativoDeStop(s); if(c) cs.add(c); });
    if(cs.size>=3){ r.rutaDispersa=true; r.motivoDispersa='Mezcla '+cs.size+' sectores ('+Array.from(cs).map(function(c){return CORREDOR_LABEL[c]||c;}).join(', ')+'). Conviene revisar o sumar un camión.'; }
  });

  /* Afinado final de distancia/tiempo con Mapbox: el ORDEN de las paradas
     ya quedó decidido arriba por el algoritmo de siempre (nearest neighbor +
     2-opt, con línea recta — rápido y gratis, perfecto para decidir orden).
     Acá, una sola vez por ruta ya armada, se le pregunta a Mapbox la
     distancia y el tiempo REALES de manejo para esa secuencia de paradas.
     Si Mapbox no está configurado, se pasó el límite seguro del mes, o la
     consulta falla, se deja tal cual la aproximación por línea recta que ya
     tenía calculada — nunca rompe el resultado. */
  for(const r of rutasFinales){
    if(!r.patente || !r.stopsOrdenados || r.stopsOrdenados.length<2) continue;
    // Guardamos la estimación de línea recta ANTES de tocar nada: es la vara
    // con la que se mide si un resultado "real" (de OSRM o Mapbox) es
    // creíble o es fruto de una dirección mal geocodificada.
    const estimadoBaseKm=r.distTotalKm;
    // Paso 1 (gratis, sin límite mensual): OSRM reordena las paradas de esta
    // ruta usando distancia real de calle, en vez de línea recta. Si OSRM no
    // responde, o el resultado es un número imposible, sigue con el orden de
    // línea recta de siempre.
    await refinarOrdenConOSRM(r, estimadoBaseKm);
    // Paso 2: Mapbox le pone el km/tiempo final más preciso a ese orden ya
    // (posiblemente) mejorado por OSRM. Si Mapbox falla, o devuelve un
    // número imposible para una ruta dentro de la Región Metropolitana, se
    // queda el número que ya haya calculado el paso anterior.
    const puntos=[BASE_LAMPA, ...r.stopsOrdenados.map(function(s){return {lat:s.lat,lon:s.lon};})];
    const real = await mapbox.calcularRutaRealMapbox(puntos);
    if(real && esDistanciaPlausible(real.km, estimadoBaseKm)){
      r.distTotalKm=Math.round(real.km*10)/10; r.minutosRealesMapbox=Math.round(real.minutos); r._distanciaFuente='mapbox';
    }
  }

  return {rutas:rutasFinales,imposibles:imposibles,sinClasificar:sinClasificar,paraOtraRegion:paraOtraRegion,excluidosMas13:excluidosMas13,sinCamion:sinCamion,fusionesSector:fusionesRealizadas,optimizacionGlobal:optimizacionGlobal,alertasComuna:alertasComuna,direccionesInconsistentes:direccionesInconsistentes};
}

function calcularEstadoRuta(r){
  if(!r.patente) return 'Sin patente asignada';
  if(r.volumen > r.mts3) return 'SUPERA CAPACIDAD MAXIMA';
  if(r.volumen > r.meta) return 'SUPERA META 70%';
  return 'OK - Dentro de meta';
}

function parseNum(v){
  if(typeof v === 'number') return v;
  return parseFloat((v||'0').toString().replace(',','.')) || 0;
}

function parseSiNo(v){
  if(v===undefined || v===null) return undefined;
  const t = String(v).trim().toUpperCase();
  if(t === '') return undefined;
  return t === 'SI' || t === 'SÍ' || t === 'S';
}

function parsearFilaPedidoBase(campos){
  campos = campos.map(function(c){ return (c||'').trim(); });
  if(campos.length === 14 || campos.length === 13){
    /* Formato principal actual del usuario (MONITOR TRANSPORTES con Entrega,
       sin Sector ni dimensiones — las medidas se toman del catálogo Imega
       Ventus por SKU, o del valor por defecto si el SKU no está en el catálogo):
       Pedido, Cantidad, Material(SKU), Descripcion, Cliente, Sucursal, Entrega,
       Volumen, Direccion, Comuna, Rotar Eje X, Rotar Eje Y, Montar, Piso 1ro/Soporta peso.
       13 columnas = igual pero sin la última columna (Piso 1ro) cuando esa
       celda venía vacía al copiar. */
    return {
      pedido: campos[0], cantidad: parseInt(campos[1],10)||1, sku: campos[2], descripcionMaterial: campos[3],
      cliente: campos[4]||'', sucursal: campos[5]||campos[4]||'', entrega: campos[6]||'',
      volumen: parseNum(campos[7]), direccion: campos[8], comuna: campos[9]||'',
      rotarEjeX: parseSiNo(campos[10]), rotarEjeY: parseSiNo(campos[11]),
      montar: parseSiNo(campos[12]), piso1ro: parseSiNo(campos[13])
    };
  }
  if(campos.length === 18 || campos.length === 17){
    /* Variante con "Nombre del cliente"/"Nombre de sucursal" separados, ENTREGA
       y además Sector + dimensiones (Largo/Ancho/Alto) al final — por si en
       algún momento la planilla sí trae esas columnas extra:
       Pedido, Cantidad, Material(SKU), Descripcion, Cliente, Sucursal, Entrega,
       Volumen, Direccion, Comuna, Sector, Largo, Ancho, Alto,
       Rotar Eje X, Rotar Eje Y, Montar, Piso 1ro/Soporta peso.
       El SECTOR que trae la planilla no se usa (el sistema calcula el suyo
       propio a partir de la comuna real); 17 columnas = igual pero sin la
       última columna (Piso 1ro) cuando esa celda venía vacía. */
    return {
      pedido: campos[0], cantidad: parseInt(campos[1],10)||1, sku: campos[2], descripcionMaterial: campos[3],
      cliente: campos[4]||'', sucursal: campos[5]||campos[4]||'', entrega: campos[6]||'',
      volumen: parseNum(campos[7]), direccion: campos[8], comuna: campos[9]||'',
      largo: parseNum(campos[11])||undefined, ancho: parseNum(campos[12])||undefined, alto: parseNum(campos[13])||undefined,
      rotarEjeX: parseSiNo(campos[14]), rotarEjeY: parseSiNo(campos[15]),
      montar: parseSiNo(campos[16]), piso1ro: parseSiNo(campos[17])
    };
  }
  if(campos.length === 12){
    return {
      pedido: campos[0], cantidad: parseInt(campos[1],10)||1, sku: campos[2], descripcionMaterial: campos[3],
      sucursal: campos[4], volumen: parseNum(campos[5]), direccion: campos[6], comuna: campos[7]||'',
      rotarEjeX: parseSiNo(campos[8]), rotarEjeY: parseSiNo(campos[9]),
      montar: parseSiNo(campos[10]), piso1ro: parseSiNo(campos[11])
    };
  }
  if(campos.length === 8){
    return {
      pedido: campos[0], cantidad: parseInt(campos[1],10)||1, sku: campos[2], descripcionMaterial: campos[3],
      sucursal: campos[4], volumen: parseNum(campos[5]), direccion: campos[6], comuna: campos[7]||''
    };
  }
  if(campos.length === 7){
    /* Fila de 7 columnas: casi siempre es el formato normal de 8 columnas
       (pedido, cantidad, sku, descripción, sucursal, volumen, dirección, comuna)
       al que le falta la COMUNA al final — muy común cuando esa celda viene
       vacía en la planilla y el copiar/pegar elimina la última columna vacía
       en vez de dejar una celda en blanco. Antes se asumía que la cantidad
       era la que faltaba, lo que desordenaba todos los campos siguientes
       (el SKU terminaba en la cantidad, la descripción en el SKU, etc.) y
       producía un error de lectura que no tenía nada que ver con la causa
       real. Si la comuna efectivamente falta, la fila igual se marcará como
       incompleta más abajo, pero con el motivo correcto. */
    return {
      pedido: campos[0], cantidad: parseInt(campos[1],10)||1, sku: campos[2], descripcionMaterial: campos[3],
      sucursal: campos[4], volumen: parseNum(campos[5]), direccion: campos[6], comuna: ''
    };
  }
  if(campos.length >= 10 && campos.length !== 12 && campos.length !== 17 && campos.length !== 18){
    return {
      pedido: campos[0], cantidad: 1, sku: campos[1], sucursal: campos[2], volumen: parseNum(campos[3]),
      direccion: campos[4], comuna: campos[5]||'',
      largo: parseNum(campos[7])||undefined, ancho: parseNum(campos[8])||undefined, alto: parseNum(campos[9])||undefined
    };
  }
  return {
    pedido: campos[0], cantidad: 1, sucursal: campos[1], volumen: parseNum(campos[2]),
    direccion: campos[3], comuna: campos[4]||''
  };
}

function parsearFilaPedido(campos){
  return normalizarVolumenLinea(parsearFilaPedidoBase(campos));
}
module.exports = {
  planificar,
  parsearFilaPedido,
  parsearFilaPedidoBase,
  calcularEstadoRuta,
  corredorOperativoDeStop,
  FLEET,
  DEPOT,
  estadoUsoMapbox: mapbox.estadoUso,
  estadoOSRM: osrm.estado,
  validarComunasLista,
  buscarDireccionesMapbox: mapbox.buscarDireccionesMapbox,
  _interno: { consolidar, nearestNeighborDesdeLampa, distanciaRutaNN, _cruces, zonaOperativaDeStop, corredorOperativoDeStop, volCarga, coordStop, calcularDistanciaKm, BASE_LAMPA, claveDireccionStop, normalizarVolumenLinea },
};
